translationPreparationTests :: TestTree
translationPreparationTests = testGroup "prepared synthesis translation"
  [ testCase "retain the source goal before inserting caller premises" $ do
      let token = FAtom False "Demo.Token"
      prepared <- expectRight $ inspectExferencePreparation
        [] [("Demo.seed", token)] token token
      inspectedEngineFragment prepared @?= token
      inspectedFitFragment prepared @?= token
      let sourceGoal = inspectedSourceGoal prepared
      inspectedSearchGoal prepared @?=
        FunctionType sourceGoal sourceGoal
      map translatedPremiseName (inspectedCallerPremises prepared)
        @?= ["Demo.seed"]
      map translatedPremiseType (inspectedCallerPremises prepared)
        @?= [sourceGoal]
      inspectedConstructorPremises prepared @?= []
      inspectedSourceArrowCount prepared @?= 0
      inspectedProviderBindings prepared @?= []
      inspectedAllProviderAssignments prepared @?= []
  , testCase "retain a distinct fitting target outside renderer closures" $ do
      let engine = FAtom False "Demo.EngineTarget"
          fit = FAll True "a" (FArr (FVar "a") (FVar "a"))
      prepared <- expectRight $ inspectExferencePreparation
        [] [] engine fit
      inspectedEngineFragment prepared @?= engine
      inspectedFitFragment prepared @?= fit
      assertBool "engine and fitting targets collapsed"
        (inspectedEngineFragment prepared /= inspectedFitFragment prepared)
  , testCase "derive aggregate provider assignments in binding order" $ do
      privateZero <- expectRight $ mkIdentifier "leantProvider0"
      privateOne <- expectRight $ mkIdentifier "leantProvider1"
      let providerType = FAll False "a" (FVar "a")
          argument name = ProviderInstantiationArgument 0
            $ FAtom False name
          first = ProviderFragWithEvidence "Demo.firstProvider"
            providerType ["a"] [[argument "Nat"], [argument "Bool"]]
          second = ProviderFragWithEvidence "Demo.secondProvider"
            providerType ["a"] [[argument "Char"]]
          goal = FAtom False "Demo.Target"
          expectedProviderInfo provider sourceAssignments binding = do
            renderAssignments <- mapM
              (\(assignment, sourceArguments) -> do
                visibleArguments <- mapM
                  (expectRight . specifiedVisibleTypeArgument . snd)
                  $ kindedProviderInstantiationAssignmentArguments assignment
                pure ProviderAssignmentInfo
                  { paiVisibleArguments = visibleArguments
                  , paiSourceArguments = sourceArguments
                  })
              $ zip (inspectedProviderAssignments binding) sourceAssignments
            let binderNames = case provider of
                  ProviderFrag{} -> Nothing
                  ProviderFragWithBinders
                    { providerTypeBinderNames = names } -> Just names
                  ProviderFragWithEvidence
                    { providerTypeBinderNames = names } -> Just names
                  ProviderFragWithLegacyCandidates
                    { providerTypeBinderNames = names } -> Just names
            pure (providerInfo
              (providerLeanName provider)
              binderNames
              (providerTypeFrag provider))
              { piAssignments = renderAssignments }
      prepared <- expectRight $ inspectExferencePreparation
        [first, second] [] goal goal
      bindings <- case inspectedProviderBindings prepared of
        [firstBinding, secondBinding] -> pure
          [firstBinding, secondBinding]
        other -> assertFailure
          ("expected two ordered provider bindings, got: " ++ show other)
          >> pure []
      map (length . inspectedProviderAssignments) bindings @?= [2, 1]
      let expectedProviderDeclarations =
            [ ValueDeclaration $ ValueSignature ()
                (inspectedProviderPrivateName binding)
                (inspectedProviderScheme binding)
            | binding <- bindings
            ]
          declarations = inspectedDeclarations prepared
      drop (length declarations - length expectedProviderDeclarations)
          declarations @?= expectedProviderDeclarations
      map kindedProviderInstantiationAssignmentProvider
          (inspectedAllProviderAssignments prepared) @?=
        [privateZero, privateZero, privateOne]
      inspectedAllProviderAssignments prepared @?=
        concatMap inspectedProviderAssignments bindings
      let providerMap = inspectedProviderMap prepared
          privateSpellings = map inspectedProviderPrivateSpelling bindings
      Map.keys providerMap @?= privateSpellings
      expectedFirst <- expectedProviderInfo first
        [[argument "Nat"], [argument "Bool"]] (bindings !! 0)
      expectedSecond <- expectedProviderInfo second
        [[argument "Char"]] (bindings !! 1)
      map
          (\binding -> Map.lookup
            (inspectedProviderPrivateSpelling binding)
            providerMap)
          bindings @?= [Just expectedFirst, Just expectedSecond]
  , testCase
      "separate exact contextual facts from legacy and malformed hints" $ do
      let token = FAtom False "Demo.ContextToken"
          natural = FParamRec True "Nat" "Nat" []
            [ ("Nat.zero", [])
            , ("Nat.succ", [FAtom False "Nat"])
            ]
          boolean = FParamInd "Bool" "Bool" []
            [("Bool.false", []), ("Bool.true", [])]
          contextualScheme className = FAll False "a"
            $ FExactContext className
                [ExactContextFragmentArgument 0 $ FVar "a"]
                token
          higherContextualScheme = FAll False "F"
            $ FExactContext "Demo.HigherC"
                [ExactContextFragmentArgument 1 $ FVar "F"]
                token
          partialHigherContextualScheme = FAll False "F" $ FAll False "a"
            $ FExactContext "Demo.PartialHigherC"
                [ ExactContextFragmentArgument 1 $
                    FApp True "F a" (AppVariable "F") [FVar "a"]
                ]
                token
          exact = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationArgument 0 natural]
            , [ProviderInstantiationArgument 0 natural]
            ]
          exactSingle = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [[ProviderInstantiationArgument 0 natural]]
          exactOther = ProviderFragWithEvidence "Demo.otherContextual"
            (contextualScheme "Demo.E") ["a"]
            [[ProviderInstantiationArgument 0 natural]]
          exactEmpty = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"] []
          higherExact = ProviderFragWithEvidence "Demo.higherContextual"
            higherContextualScheme ["F"]
            [[ProviderInstantiationNominalArgument 1 "Demo.Higher" []]]
          partialHigherExact = ProviderFragWithEvidence
            "Demo.partialHigherContextual" partialHigherContextualScheme
            ["F", "a"]
            [ [ ProviderInstantiationNominalArgument 2 "Demo.Pair" []
              , ProviderInstantiationArgument 0 natural
              ]
            ]
          openHigher = ProviderFragWithBinders "Demo.openHigher"
            (FExactContext "Demo.HigherC"
              [ExactContextFragmentArgument 1 $ FVar "F"]
              token)
            ["F"]
          higherWithNestedFallback = ProviderFragWithEvidence
            "Demo.higherContextual" higherContextualScheme ["F"]
            [ [ ProviderInstantiationNominalArgument 1 "Demo.BadHigher"
                  [FInst "Demo.Nested Nat" natural]
              ]
            , [ProviderInstantiationNominalArgument 1 "Demo.Higher" []]
            ]
          trialRejected = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [[ProviderInstantiationNominalArgument 1 "Demo.Higher" []]]
          trialThenGood = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationNominalArgument 1 "Demo.Higher" []]
            , [ProviderInstantiationArgument 0 natural]
            ]
          goodThenTrial = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationArgument 0 natural]
            , [ProviderInstantiationNominalArgument 1 "Demo.Higher" []]
            ]
          multiContextualScheme = FAll False "a" $ FAll False "b"
            $ FExactContext "Demo.C"
                [ExactContextFragmentArgument 0 $ FVar "a"]
            $ FExactContext "Demo.D"
                [ExactContextFragmentArgument 0 $ FVar "b"]
                token
          multiAccepted = ProviderFragWithEvidence "Demo.multiContextual"
            multiContextualScheme ["a", "b"]
            [ [ ProviderInstantiationArgument 0 natural
              , ProviderInstantiationArgument 0 boolean
              ]
            ]
          multiRejected = ProviderFragWithEvidence "Demo.multiContextual"
            multiContextualScheme ["a", "b"]
            [ [ ProviderInstantiationArgument 0 natural
              , ProviderInstantiationNominalArgument 1 "Demo.Higher" []
              ]
            ]
          orderedVectors = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationArgument 0 natural]
            , [ProviderInstantiationArgument 0 boolean]
            ]
          legacy = ProviderFragWithLegacyCandidates "Demo.contextual"
            (contextualScheme "Demo.C") ["a"] [natural]
          instanceConstraints prepared =
            [ constraint
            | InstanceDeclaration () [] [] constraint <-
                inspectedDeclarations prepared
            ]
      exactPrepared <- expectRight $ inspectExferencePreparation
        [exact] [] token token
      (contextClass, groundArgument) <- case
          ( inspectedProviderBindings exactPrepared
          , instanceConstraints exactPrepared
          ) of
        ( [binding]
          , [Constraint factClass [factArgument]]
          ) -> case inspectedProviderScheme binding of
            ForallType [binder]
                [Constraint schemeClass [TypeVariable occurrence]] _ -> do
              occurrence @?= binder
              factClass @?= schemeClass
              inspectedProviderAssignments binding @?= []
              inspectedAllProviderAssignments exactPrepared @?= []
              pure (schemeClass, factArgument)
            scheme -> assertFailure
              ("exact provider context was erased: " ++ show scheme)
                >> error "unreachable"
        (bindings, facts) -> assertFailure
          ("exact contextual preparation retained unexpected bindings/facts: "
            ++ show (bindings, facts)) >> error "unreachable"
      assertBool "exact contextual evidence minted a quantified fact"
        $ not $ Djex.containsForall groundArgument
      assertBool "exact contextual evidence minted a non-ground fact"
        $ Set.null $ Djex.freeVariables groundArgument

      fragHasUnsupportedInstanceBinder higherContextualScheme @?= False
      higherPrepared <- expectRight $ inspectExferencePreparation
        [higherExact] [] token token
      case ( inspectedProviderBindings higherPrepared
           , instanceConstraints higherPrepared
           ) of
        ( [binding]
          , [Constraint factClass [factArgument]]
          ) -> case inspectedProviderScheme binding of
            ForallType [binder]
                [Constraint schemeClass [TypeVariable occurrence]] _ -> do
              occurrence @?= binder
              factClass @?= schemeClass
              inspectedProviderAssignments binding @?= []
              inspectedAllProviderAssignments higherPrepared @?= []
              (Djex.nameSpelling factClass >>=
                  (`Map.lookup` inspectedTypeMap higherPrepared)) @?=
                Just "Demo.HigherC"
              case factArgument of
                TypeConstructor typeName ->
                  (Djex.nameSpelling typeName >>=
                      (`Map.lookup` inspectedTypeMap higherPrepared)) @?=
                    Just "Demo.Higher"
                other -> assertFailure $
                  "higher-kinded fact lost its nominal head: " ++ show other
              assertBool "higher-kinded fact retained a forall"
                $ not $ Djex.containsForall factArgument
              assertBool "higher-kinded fact retained a free variable"
                $ Set.null $ Djex.freeVariables factArgument
            scheme -> assertFailure $
              "bound higher-kinded context was erased: " ++ show scheme
        other -> assertFailure $
          "bound higher-kinded evidence retained unexpected authority: "
            ++ show other
      higherWithNestedPrepared <- expectRight $ inspectExferencePreparation
        [higherWithNestedFallback] [] token token
      higherWithNestedPrepared @?= higherPrepared
      partialHigherPrepared <- expectRight $ inspectExferencePreparation
        [partialHigherExact] [] token token
      case ( inspectedProviderBindings partialHigherPrepared
           , instanceConstraints partialHigherPrepared
           ) of
        ( [binding]
          , [Constraint factClass
              [TypeApplication (TypeConstructor pairName) factElement]]
          ) -> case inspectedProviderScheme binding of
            ForallType [functionBinder, argumentBinder]
                [ Constraint schemeClass
                    [ TypeApplication
                        (TypeVariable functionOccurrence)
                        (TypeVariable argumentOccurrence)
                    ]
                ] _ -> do
              functionOccurrence @?= functionBinder
              argumentOccurrence @?= argumentBinder
              factClass @?= schemeClass
              inspectedProviderAssignments binding @?= []
              inspectedAllProviderAssignments partialHigherPrepared @?= []
              (Djex.nameSpelling factClass >>=
                  (`Map.lookup` inspectedTypeMap partialHigherPrepared)) @?=
                Just "Demo.PartialHigherC"
              (Djex.nameSpelling pairName >>=
                  (`Map.lookup` inspectedTypeMap partialHigherPrepared)) @?=
                Just "Demo.Pair"
              case factElement of
                TypeConstructor elementName ->
                  (Djex.nameSpelling elementName >>=
                      (`Map.lookup`
                        inspectedTypeMap partialHigherPrepared)) @?=
                    Just "Nat"
                other -> assertFailure $
                  "partial higher-kinded fact lost its Nat argument: "
                    ++ show other
              assertBool "partial higher-kinded fact retained a forall"
                $ not $ Djex.containsForall factElement
              assertBool "partial higher-kinded fact retained a free variable"
                $ Set.null $ Djex.freeVariables factElement
            scheme -> assertFailure $
              "partial bound higher-kinded context was erased: " ++ show scheme
        other -> assertFailure $
          "partial bound higher-kinded evidence retained unexpected authority: "
            ++ show other

      legacyPrepared <- expectRight $ inspectExferencePreparation
        [legacy] [] token token
      instanceConstraints legacyPrepared @?= []
      case inspectedProviderBindings legacyPrepared of
        [binding] -> do
          case inspectedProviderScheme binding of
            ForallType [_] [] _ -> pure ()
            scheme -> assertFailure $
              "legacy candidate provenance retained provider context: "
                ++ show scheme
          length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "legacy preparation retained unexpected bindings: " ++ show bindings
      assertBool "legacy preparation accidentally retained a context class"
        $ all (/= contextClass)
        $ [ className
          | ClassDeclaration () className _ _ _ <-
              inspectedDeclarations legacyPrepared
          ]
      emptyPrepared <- expectRight $ inspectExferencePreparation
        [exactEmpty] [] token token
      instanceConstraints emptyPrepared @?= []
      inspectedAllProviderAssignments emptyPrepared @?= []
      case inspectedProviderBindings emptyPrepared of
        [binding] -> case inspectedProviderScheme binding of
          ForallType [_] [] _ -> pure ()
          scheme -> assertFailure $
            "empty exact evidence retained provider context: " ++ show scheme
        bindings -> assertFailure $
          "empty exact evidence retained unexpected bindings: "
            ++ show bindings
      trialRejectedPrepared <- expectRight $ inspectExferencePreparation
        [trialRejected] [] token token
      instanceConstraints trialRejectedPrepared @?= []
      case inspectedProviderBindings trialRejectedPrepared of
        [binding] -> do
          case inspectedProviderScheme binding of
            ForallType [_] [] _ -> pure ()
            scheme -> assertFailure $
              "rejected fact trial retained provider context: " ++ show scheme
          length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "rejected fact trial lost its fallback binding: " ++ show bindings
      multiAcceptedPrepared <- expectRight $ inspectExferencePreparation
        [multiAccepted] [] token token
      case ( inspectedProviderBindings multiAcceptedPrepared
           , instanceConstraints multiAcceptedPrepared
           ) of
        ( [binding]
          , [ Constraint firstFactClass [firstFactArgument]
            , Constraint secondFactClass [secondFactArgument]
            ]
          ) -> case inspectedProviderScheme binding of
            ForallType [firstBinder, secondBinder]
                [ Constraint firstSchemeClass
                    [TypeVariable firstOccurrence]
                , Constraint secondSchemeClass
                    [TypeVariable secondOccurrence]
                ] _ -> do
              (firstOccurrence, secondOccurrence) @?=
                (firstBinder, secondBinder)
              (firstFactClass, secondFactClass) @?=
                (firstSchemeClass, secondSchemeClass)
              map
                  (\className -> Djex.nameSpelling className >>=
                    (`Map.lookup` inspectedTypeMap multiAcceptedPrepared))
                  [firstFactClass, secondFactClass] @?=
                [Just "Demo.C", Just "Demo.D"]
              assertBool "ordered contextual facts collapsed their classes"
                $ firstFactClass /= secondFactClass
              let leanFactType typeExpression = case typeExpression of
                    TypeConstructor typeName -> Djex.nameSpelling typeName >>=
                      (`Map.lookup` inspectedTypeMap multiAcceptedPrepared)
                    _ -> Nothing
              map leanFactType [firstFactArgument, secondFactArgument] @?=
                [Just "Nat", Just "Bool"]
            scheme -> assertFailure $
              "multi-constraint provider lost its source context order: "
                ++ show scheme
        other -> assertFailure $
          "multi-constraint fact group was not retained atomically: "
            ++ show other
      multiRejectedPrepared <- expectRight $ inspectExferencePreparation
        [multiRejected] [] token token
      instanceConstraints multiRejectedPrepared @?= []
      assertBool "fallback did not commit its natural argument family"
        $ "Nat" `elem` Map.elems (inspectedTypeMap multiRejectedPrepared)
      assertBool "fallback did not commit its higher-kinded argument family"
        $ "Demo.Higher" `elem`
            Map.elems (inspectedTypeMap multiRejectedPrepared)
      case inspectedProviderBindings multiRejectedPrepared of
        [binding] -> do
          case inspectedProviderScheme binding of
            ForallType [_, _] [] _ -> pure ()
            scheme -> assertFailure $
              "partially rejected fact group retained a context: "
                ++ show scheme
          length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "partially rejected fact group lost its fallback binding: "
            ++ show bindings
      orderedPrepared <- expectRight $ inspectExferencePreparation
        [orderedVectors] [] token token
      case instanceConstraints orderedPrepared of
        [ Constraint firstClass [firstArgument]
          , Constraint secondClass [secondArgument]
          ] -> do
            firstClass @?= secondClass
            let leanTypeName typeExpression = case typeExpression of
                  TypeConstructor typeName -> Djex.nameSpelling typeName >>=
                    (`Map.lookup` inspectedTypeMap orderedPrepared)
                  _ -> Nothing
            map leanTypeName [firstArgument, secondArgument] @?=
              [Just "Nat", Just "Bool"]
        facts -> assertFailure $
          "distinct exact vectors lost source fact order: " ++ show facts
      providerOrderedPrepared <- expectRight $ inspectExferencePreparation
        [exactSingle, exactOther] [] token token
      case instanceConstraints providerOrderedPrepared of
        [Constraint firstClass _, Constraint secondClass _] ->
          map
              (\className -> Djex.nameSpelling className >>=
                (`Map.lookup` inspectedTypeMap providerOrderedPrepared))
              [firstClass, secondClass] @?=
            [Just "Demo.C", Just "Demo.E"]
        facts -> assertFailure $
          "distinct providers lost source fact order: " ++ show facts
      let exactDjinn = synthesizeWithProviders
            EngineDjinn 1024 [exactSingle] token
          legacyDjinn = synthesizeWithProviders
            EngineDjinn 1024 [legacy] token
      exactDjinn @?= legacyDjinn
      case exactDjinn of
        Right (SynthCandidates groups _) -> assertBool
          ("context-erased Djinn compatibility found no provider: "
            ++ show groups)
          $ any ("Demo.contextual" `isInfixOf`) $ concat groups
        outcome -> assertFailure $
          "context-erased Djinn compatibility failed: " ++ show outcome

      let recipient = ProviderFragWithBinders "Demo.contextRecipient"
            (contextualScheme "Demo.C") ["a"]
      crossPrepared <- expectRight $ inspectExferencePreparation
        [exactSingle, recipient] [] token token
      crossFact <- case instanceConstraints crossPrepared of
        [fact] -> pure fact
        facts -> assertFailure
          ("cross-provider preparation retained unexpected facts: "
            ++ show facts) >> error "unreachable"
      case inspectedProviderBindings crossPrepared of
        [donorBinding, recipientBinding] -> do
          inspectedProviderAssignments donorBinding @?= []
          inspectedProviderAssignments recipientBinding @?= []
          case inspectedProviderScheme recipientBinding of
            ForallType [_] [_] _ -> pure ()
            scheme -> assertFailure $
              "cross-provider recipient lost its context: " ++ show scheme
          let declarations = inspectedDeclarations crossPrepared
          drop (length declarations - 3) declarations @?=
            [ ValueDeclaration $ ValueSignature ()
                (inspectedProviderPrivateName donorBinding)
                (inspectedProviderScheme donorBinding)
            , ValueDeclaration $ ValueSignature ()
                (inspectedProviderPrivateName recipientBinding)
                (inspectedProviderScheme recipientBinding)
            , InstanceDeclaration () [] [] crossFact
            ]
        bindings -> assertFailure $
          "cross-provider preparation retained unexpected bindings: "
            ++ show bindings
      let recipientResiduals outcome = case outcome of
            DetailedSynthCandidates groups _ ->
              [ Djex.candidateResidualConstraints
                  $ Djex.typedCandidateCompatibility
                  $ typedCandidateSemanticCandidate semantic
              | group <- groups
              , any ("Demo.contextRecipient" `isInfixOf`)
                  $ detailedCandidateGroupVariants group
              , Just semantic <-
                  [detailedCandidateGroupSemanticSidecar group]
              ]
            _ -> []
      recipientOnly <- expectRight $
        synthesizeWithProvidersSkippingDetailed
          EngineExference 1024 Set.empty [recipient] token
      assertBool
        "the recipient resolved without the donor's global C Nat fact"
        $ all (not . null) $ recipientResiduals recipientOnly
      crossDetailed <- expectRight $
        synthesizeWithProvidersSkippingDetailed
          EngineExference 1024 Set.empty [exactSingle, recipient] token
      assertBool
        ("a global C Nat fact did not discharge the sibling provider: "
          ++ show (recipientResiduals crossDetailed))
        $ any null $ recipientResiduals crossDetailed

      let quantified = FAll True "x"
            $ FArr (FVar "x") (FVar "x")
          malformed name className argument = ProviderFragWithEvidence name
            (contextualScheme className) ["a"]
            [[ProviderInstantiationArgument 0 argument]]
          badForall = malformed "Demo.badForall" "Demo.ForallClass"
            quantified
          failingFallback = ProviderFragWithEvidence "Demo.badForall"
            (contextualScheme "Demo.ForallClass") ["a"]
            [ [ProviderInstantiationArgument 0 $ FVar "unbound"]
            , [ProviderInstantiationArgument 0 quantified]
            ]
          mixedVector = ProviderFragWithEvidence "Demo.contextual"
            (contextualScheme "Demo.C") ["a"]
            [ [ProviderInstantiationArgument 0 quantified]
            , [ProviderInstantiationArgument 0 natural]
            ]
      fallbackPrepared <- expectRight $ inspectExferencePreparation
        [badForall] [] token token
      instanceConstraints fallbackPrepared @?= []
      case inspectedProviderBindings fallbackPrepared of
        [binding] -> do
          case inspectedProviderScheme binding of
            ForallType [_] [] _ -> pure ()
            scheme -> assertFailure $
              "resolver-ineligible exact evidence kept its context: "
                ++ show scheme
          length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "context-erased exact fallback retained unexpected bindings: "
            ++ show bindings
      failingFallbackPrepared <- expectRight $ inspectExferencePreparation
        [failingFallback] [] token token
      failingFallbackPrepared @?= fallbackPrepared
      exactSinglePrepared <- expectRight $ inspectExferencePreparation
        [exactSingle] [] token token
      openSiblingPrepared <- expectRight $ inspectExferencePreparation
        [openHigher, exactSingle] [] token token
      openSiblingPrepared @?= exactSinglePrepared
      trialThenGoodPrepared <- expectRight $ inspectExferencePreparation
        [trialThenGood] [] token token
      trialThenGoodPrepared @?= exactSinglePrepared
      goodThenTrialPrepared <- expectRight $ inspectExferencePreparation
        [goodThenTrial] [] token token
      goodThenTrialPrepared @?= exactSinglePrepared
      mixedVectorPrepared <- expectRight $ inspectExferencePreparation
        [mixedVector] [] token token
      mixedVectorPrepared @?= exactSinglePrepared
      mixedPrepared <- expectRight $ inspectExferencePreparation
        [badForall, exact] [] token token
      case instanceConstraints mixedPrepared of
        [Constraint factClass [argument]] -> do
          (Djex.nameSpelling factClass >>=
              (`Map.lookup` inspectedTypeMap mixedPrepared)) @?=
            Just "Demo.C"
          argument @?= groundArgument
          assertBool "a quantified evidence vector minted an instance"
            $ not $ Djex.containsForall argument
          assertBool "the good ground fact retained a free variable"
            $ Set.null $ Djex.freeVariables argument
        facts -> assertFailure $
          "malformed evidence poisoned or expanded the good fact set: "
            ++ show facts
  , testCase "share alpha-renamed bound contextual family schemas" $ do
      let token = FAtom False "Demo.ContextSchemaToken"
          field functionBinder argumentBinder =
            FAll False functionBinder $ FAll False argumentBinder $
              FExactContext "Demo.ContextSchema"
                [ ExactContextFragmentArgument 1 $
                    FApp True
                      (functionBinder ++ " " ++ argumentBinder)
                      (AppVariable functionBinder)
                      [FVar argumentBinder]
                ]
                token
          family key parameter fixedField =
            FParamInd "Demo.ContextBox" key [FVar parameter]
              [("Demo.ContextBox.mk", [fixedField])]
          left = family "Demo.ContextBox left" "left"
            $ field "F" "a"
          right = family "Demo.ContextBox right" "right"
            $ field "G" "b"
          goal = FAll False "left" $ FAll False "right" $
            FArr left $ FArr right token
      prepared <- expectRight $ inspectExferencePreparation [] [] goal goal
      length (inspectedSemanticFamilyBindings prepared) @?= 1
      let contextBoxDeclarations =
            [ typeName
            | DataTypeDeclaration _ typeName _ _ <-
                inspectedDeclarations prepared
            , (Djex.nameSpelling typeName >>=
                (`Map.lookup` inspectedTypeMap prepared)) ==
                Just "Demo.ContextBox"
            ]
      length contextBoxDeclarations @?= 1
  , testCase
      "drop downgraded nested contexts from nominal evidence locally" $ do
      let token = FAtom False "Demo.ContextToken"
          natural = FParamRec True "Nat" "Nat" []
            [ ("Nat.zero", [])
            , ("Nat.succ", [FAtom False "Nat"])
            ]
          naturalWire =
            "(param-rec complete \"Nat\" \"Nat\" (params) "
              ++ "(ctor \"Nat.zero\") "
              ++ "(ctor \"Nat.succ\" (atom unsafe \"Nat\")))"
          nestedWire =
            "(inst \"Demo.Nested Nat\" " ++ naturalWire ++ ")"
          badArgumentWire =
            "(kinded 1 (nominal \"Demo.Higher\" "
              ++ nestedWire ++ "))"
          goodArgumentWire = "(kinded 0 " ++ naturalWire ++ ")"
          providerScheme = FAll False "a"
            $ FExactContext "Demo.C"
                [ExactContextFragmentArgument 0 $ FVar "a"]
                token
          providerSchemeWire =
            "(alli \"a\" (exact-context \"Demo.C\" (arguments "
              ++ "(kinded 0 (var \"a\"))) "
              ++ "(atom unsafe \"Demo.ContextToken\")))"
          inventory =
            "(providers (provider \"Demo.contextual\" (binders \"a\") "
              ++ "(instantiations (args " ++ badArgumentWire ++ ") "
              ++ "(args " ++ goodArgumentWire ++ ")) "
              ++ providerSchemeWire ++ "))"
          downgraded = ProviderFragWithEvidence "Demo.contextual"
            providerScheme ["a"]
            [ [ ProviderInstantiationNominalArgument 1 "Demo.Higher"
                  [FInst "Demo.Nested Nat" natural]
              ]
            , [ProviderInstantiationArgument 0 natural]
            ]
          validOnly = ProviderFragWithEvidence "Demo.contextual"
            providerScheme ["a"]
            [[ProviderInstantiationArgument 0 natural]]
          instanceConstraints prepared =
            [ constraint
            | InstanceDeclaration () [] [] constraint <-
                inspectedDeclarations prepared
            ]
      parsed <- expectRight $ parseProviderSexp inventory
      parsed @?= [downgraded]
      expected <- expectRight $ inspectExferencePreparation
        [validOnly] [] token token
      actual <- expectRight $ inspectExferencePreparation
        parsed [] token token
      actual @?= expected
      case ( inspectedProviderBindings actual
           , instanceConstraints actual
           ) of
        ( [binding], [Constraint className [argument]] ) -> do
          inspectedProviderAssignments binding @?= []
          (Djex.nameSpelling className >>=
              (`Map.lookup` inspectedTypeMap actual)) @?= Just "Demo.C"
          case argument of
            TypeConstructor typeName ->
              (Djex.nameSpelling typeName >>=
                  (`Map.lookup` inspectedTypeMap actual)) @?= Just "Nat"
            other -> assertFailure $
              "surviving exact fact lost Nat identity: " ++ show other
        other -> assertFailure $
          "nested nominal context changed surviving authority: " ++ show other
  , testCase
      "exclude visible-argument failures from fallback family planning" $ do
      let token = FAtom False "Demo.PlanningToken"
          quantified = FAll True "x"
            $ FArr (FVar "x") (FVar "x")
          planned argument = FParamInd
            "Demo.Planned" "Demo.Planned argument" [argument]
            [("Demo.Planned.mk", [argument])]
          plannedFallbackArgument = planned quantified
          planningFailureArgument = FApp False
            "Demo.Planned unbound" (AppNominal "Demo.Planned")
            [FVar "unbound"]
          provider assignments = ProviderFragWithEvidence
            "Demo.plannedContextual"
            (FAll False "a"
              $ FExactContext "Demo.PlanningC"
                  [ExactContextFragmentArgument 0 $ FVar "a"]
                  token)
            ["a"] assignments
          fallbackOnly = provider
            [[ProviderInstantiationArgument 0 plannedFallbackArgument]]
          failureThenFallback = provider
            [ [ProviderInstantiationArgument 0 planningFailureArgument]
            , [ProviderInstantiationArgument 0 plannedFallbackArgument]
            ]
          instanceConstraints prepared =
            [ constraint
            | InstanceDeclaration () [] [] constraint <-
                inspectedDeclarations prepared
            ]
      fragHasDepth planningFailureArgument @?= False
      fragHasInstanceBinder planningFailureArgument @?= False
      fragHasUnsupportedInstanceBinder planningFailureArgument @?= False
      expected <- expectRight $ inspectExferencePreparation
        [fallbackOnly] [] token token
      instanceConstraints expected @?= []
      case inspectedProviderBindings expected of
        [binding] -> length (inspectedProviderAssignments binding) @?= 1
        bindings -> assertFailure $
          "planned fallback retained unexpected bindings: " ++ show bindings
      assertBool "planned fallback lost its structural family"
        $ any
          (\declaration -> case declaration of
            DataTypeDeclaration () typeName [_] [_] ->
              (Djex.nameSpelling typeName >>=
                (`Map.lookup` inspectedTypeMap expected)) ==
                  Just "Demo.Planned"
            _ -> False)
          (inspectedDeclarations expected)
      actual <- expectRight $ inspectExferencePreparation
        [failureThenFallback] [] token token
      actual @?= expected
  , testCase "bind private providers, assignments, and exact family maps" $ do
      privateProvider <- expectRight $ mkIdentifier "leantProvider0"
      privateType <- expectRight $ mkIdentifier "LeantType0"
      let natural = FAtom False "Nat"
          box key argument =
            FApp False key (AppNominal "Demo.Box") [argument]
          provider = ProviderFragWithEvidence "Demo.chooseBox"
            (FAll False "a" (box "Demo.Box a" (FVar "a")))
            ["a"] [[ProviderInstantiationArgument 0 natural]]
          goal = box "Demo.Box Nat" natural
      prepared <- expectRight $ inspectExferencePreparation
        [provider] [] goal goal
      inspectedSourceGoal prepared @?= inspectedSearchGoal prepared
      case inspectedProviderBindings prepared of
        [binding] -> do
          inspectedProviderSourceName binding @?= "Demo.chooseBox"
          inspectedProviderPrivateName binding @?= privateProvider
          inspectedProviderPrivateSpelling binding @?= "leantProvider0"
          case inspectedProviderScheme binding of
            ForallType [binder] []
                (TypeApplication (TypeConstructor family)
                  (TypeVariable occurrence)) -> do
              family @?= privateType
              occurrence @?= binder
            scheme -> assertFailure $
              "expected the exact private provider scheme, got: "
                ++ show scheme
          case inspectedProviderAssignments binding of
            [assignment] -> do
              kindedProviderInstantiationAssignmentProvider assignment
                @?= privateProvider
              length
                  (kindedProviderInstantiationAssignmentArguments assignment)
                @?= 1
              inspectedAllProviderAssignments prepared @?= [assignment]
            assignments -> assertFailure $
              "expected one exact provider assignment, got: "
                ++ show assignments
        bindings -> assertFailure $
          "expected one private provider binding, got: " ++ show bindings
      fmap piLeanName (Map.lookup "leantProvider0"
          $ inspectedProviderMap prepared)
        @?= Just "Demo.chooseBox"
      Map.lookup "LeantType0" (inspectedTypeMap prepared)
        @?= Just "Demo.Box"
  , testCase "retain constructor and type maps from one structural family" $ do
      let flag = FParamInd "Demo.Flag" "Demo.Flag" []
            [("Demo.Flag.mk", [])]
      prepared <- expectRight $ inspectExferencePreparation
        [] [] flag flag
      inspectedConstructorPrivateNames prepared @?=
        ["LeantFamilyC0_0"]
      Map.lookup "LeantType0" (inspectedTypeMap prepared)
        @?= Just "Demo.Flag"
      inspectedFamiliesComplete prepared @?= True
  ]

providerParserTests :: TestTree
providerParserTests = testGroup "provider inventory parser"
  [ testCase "retains exact Lean names and structural types" $ do
      parseProviderSexp
          "(providers (provider \"Demo.toBool\" (-> (atom unsafe \"Nat\") \
          \(ind \"Bool\" (ctor \"Bool.false\") (ctor \"Bool.true\")))))"
        @?= Right
          [ ProviderFrag "Demo.toBool"
              (FArr
                (FAtom False "Nat")
                (FInd "Bool" [("Bool.false", []), ("Bool.true", [])]))
          ]
  , testCase "retains recursive inventory status and applied parameters" $ do
      parseProviderSexp
          "(providers (provider \"Demo.step\" (rec partial \"Demo.Phantom α\" \
          \(params (var \"α\")) (ctor \"Demo.Phantom.base\") \
          \(ctor \"Demo.Phantom.next\" \
          \(atom unsafe \"Demo.Phantom α\")))))"
        @?= Right
          [ ProviderFrag "Demo.step"
              (FRec False "Demo.Phantom α" [FVar "α"]
                [ ("Demo.Phantom.base", [])
                , ("Demo.Phantom.next",
                    [FAtom False "Demo.Phantom α"])
                ])
          ]
  , testCase "retain nominal application arity and argument order" $
      parseProviderSexp
          "(providers (provider \"Demo.bi\" \
          \(app unsafe \"Demo.Bi \945 \946\" (app-nominal \"Demo.Bi\") \
          \(var \"\945\") (var \"\946\"))))"
        @?= Right
          [ ProviderFrag "Demo.bi"
              (FApp False "Demo.Bi \945 \946" (AppNominal "Demo.Bi")
                [FVar "\945", FVar "\946"])
          ]
  , testCase "accepts an empty bounded inventory" $
      parseProviderSexp "(providers)" @?= Right []
  , testCase "retain original Lean names for provider type binders" $
      parseProviderSexp
          "(providers (provider \"Demo.global\" (binders \"a\") \
          \(alli \"s0\" (atom unsafe \"Demo.Token\"))))"
        @?= Right
          [ ProviderFragWithBinders "Demo.global"
              (FAll False "s0" (FAtom False "Demo.Token")) ["a"]
          ]
  , testCase "distinguish live empty binder metadata from legacy input" $
      parseProviderSexp
          "(providers (provider \"Demo.token\" (binders) \
          \(atom unsafe \"Demo.Token\")))"
        @?= Right
          [ ProviderFragWithBinders "Demo.token"
              (FAtom False "Demo.Token") []
          ]
  , testCase "preserve legacy candidate provenance without exact authority" $
      parseProviderSexp
          "(providers (provider \"Gap.global\" (binders \"a\") \
          \(candidates \
          \(all \"s0\" (-> (var \"s0\") (var \"s0\"))) \
          \(atom unsafe \"Nat\")) \
          \(alli \"i0\" (atom unsafe \"Gap.Token\"))))"
        @?= Right
          [ ProviderFragWithLegacyCandidates "Gap.global"
              (FAll False "i0" (FAtom False "Gap.Token"))
              ["a"]
              [ FAll True "s0" (FArr (FVar "s0") (FVar "s0"))
              , FAtom False "Nat"
              ]
          ]
  , testCase "distinguish exact ordered provider instantiations" $
      parseProviderSexp
          "(providers (provider \"Gap.global\" (binders \"a\" \"b\") \
          \(instantiations \
          \(args (all \"s0\" (-> (var \"s0\") (var \"s0\"))) \
          \(all \"s1\" (-> (var \"s1\") \
          \(-> (var \"s1\") (var \"s1\"))))) \
          \(args (atom unsafe \"Nat\") (atom unsafe \"Bool\"))) \
          \(alli \"a\" (alli \"b\" (atom unsafe \"Gap.Token\")))))"
        @?= Right
          [ ProviderFragWithEvidence "Gap.global"
              (FAll False "a"
                (FAll False "b" (FAtom False "Gap.Token")))
              ["a", "b"]
              [ [ ProviderInstantiationArgument 0
                    (FAll True "s0" (FArr (FVar "s0") (FVar "s0")))
                , ProviderInstantiationArgument 0
                    (FAll True "s1"
                      (FArr (FVar "s1")
                        (FArr (FVar "s1") (FVar "s1"))))
                ]
              , [ ProviderInstantiationArgument 0 (FAtom False "Nat")
                , ProviderInstantiationArgument 0 (FAtom False "Bool")
                ]
              ]
          ]
  , testCase "retain explicit provider argument kinds" $
      parseProviderSexp
          "(providers (provider \"Gap.global\" (binders \"F\" \"a\") \
          \(instantiations (args \
          \(kinded 1 (atom unsafe \"Gap.Wrap\")) \
          \(kinded 0 (atom unsafe \"Nat\")))) \
          \(alli \"F\" (alli \"a\" (-> \
          \(app unsafe \"F a\" (app-variable \"F\") (var \"a\")) \
          \(atom unsafe \"Gap.Token\"))))))"
        @?= Right
          [ ProviderFragWithEvidence "Gap.global"
              (FAll False "F" (FAll False "a"
                (FArr
                  (FApp False "F a" (AppVariable "F") [FVar "a"])
                  (FAtom False "Gap.Token"))))
              ["F", "a"]
              [ [ ProviderInstantiationArgument 1
                    (FAtom False "Gap.Wrap")
                , ProviderInstantiationArgument 0 (FAtom False "Nat")
                ]
              ]
          ]
  , testCase "retain bounded exact Lean provider forall domains" $
      parseProviderSexp
          ("(providers (provider \"Gap.global\" (binders \"a\") "
            ++ "(instantiations (args (kinded 0 (exact "
            ++ "(domains prop type) "
            ++ "(alli \"P\" (all \"A\" (-> (var \"P\") "
            ++ "(var \"A\")))))))) (alli \"a\" "
            ++ "(atom unsafe \"Gap.Token\"))))")
        @?= Right
          [ ProviderFragWithEvidence "Gap.global"
              (FAll False "a" (FAtom False "Gap.Token"))
              ["a"]
              [ [ ProviderInstantiationExactArgument 0
                    (FAll False "P" $ FAll True "A" $
                      FArr (FVar "P") (FVar "A"))
                    [ProviderForallDomainProp, ProviderForallDomainType]
                ]
              ]
          ]
  , testCase "retain structured contextual exact provider assignments" $
      let contextual = FAll False "A" $
            FExactContext "Inhabited"
              [ExactContextFragmentArgument 0 (FVar "A")] $
              FArr (FVar "A") (FVar "A")
          higherContextual =
            FExactContext "Functor"
              [ExactContextFragmentArgument 1 (FAtom False "List")] $
              FArr (FAtom False "Nat") (FAtom False "Nat")
      in do
        parseProviderSexp
            ("(providers (provider \"ContextualOnly.chosen\" "
              ++ "(binders \"a\") (instantiations (args (kinded 0 "
              ++ "(exact (domains type) (alli \"A\" "
              ++ "(exact-context \"Inhabited\" (arguments "
              ++ "(kinded 0 (var \"A\"))) "
              ++ "(-> (var \"A\") (var \"A\")))))))) "
              ++ "(alli \"a\" "
              ++ "(atom unsafe \"ContextualOnly.Token\"))))")
          @?= Right
            [ ProviderFragWithEvidence "ContextualOnly.chosen"
                (FAll False "a" (FAtom False "ContextualOnly.Token"))
                ["a"]
                [ [ ProviderInstantiationExactArgument 0 contextual
                      [ProviderForallDomainType]
                  ]
                ]
            ]
        fragHasInstanceBinder contextual @?= True
        fragHasUnsupportedInstanceBinder contextual @?= False
        parseProviderSexp
            ("(providers (provider \"HigherContext.chosen\" "
              ++ "(binders \"a\") (instantiations (args (kinded 0 "
              ++ "(exact (domains) "
              ++ "(exact-context \"Functor\" (arguments "
              ++ "(kinded 1 (atom unsafe \"List\"))) "
              ++ "(-> (atom unsafe \"Nat\") "
              ++ "(atom unsafe \"Nat\"))))))) "
              ++ "(alli \"a\" "
              ++ "(atom unsafe \"HigherContext.Token\"))))")
          @?= Right
            [ ProviderFragWithEvidence "HigherContext.chosen"
                (FAll False "a" (FAtom False "HigherContext.Token"))
                ["a"]
                [ [ ProviderInstantiationExactArgument 0 higherContextual []
                  ]
                ]
            ]
        fragHasUnsupportedInstanceBinder higherContextual @?= False
  , testCase "retain canonical structural higher-kinded context arguments" $
      let natural = FAtom False "Nat"
          contextual = FExactContext "Structural.Context"
            [ ExactContextNominalArgument 2 "Prod" []
            , ExactContextNominalArgument 1 "Sum" [natural]
            ]
            (FArr natural natural)
      in do
        parseProviderSexp
            ("(providers (provider \"Structural.chosen\" "
              ++ "(binders \"selected\") "
              ++ "(instantiations (args (kinded 0 "
              ++ "(exact (domains) "
              ++ "(exact-context \"Structural.Context\" (arguments "
              ++ "(kinded 2 (nominal \"Prod\")) "
              ++ "(kinded 1 (nominal \"Sum\" "
              ++ "(atom unsafe \"Nat\")))) "
              ++ "(-> (atom unsafe \"Nat\") "
              ++ "(atom unsafe \"Nat\"))))))) "
              ++ "(alli \"selected\" "
              ++ "(atom unsafe \"Structural.Token\"))))")
          @?= Right
            [ ProviderFragWithEvidence "Structural.chosen"
                (FAll False "selected" (FAtom False "Structural.Token"))
                ["selected"]
                [ [ ProviderInstantiationExactArgument 0 contextual []
                  ]
                ]
            ]
        fragHasUnsupportedInstanceBinder contextual @?= False
  , testCase "retain provider contexts while rejecting ordinary contexts" $ do
      let contextual =
            "(exact-context \"Gap.C\" (arguments) "
              ++ "(atom unsafe \"Gap.Token\"))"
          expected = Left
            "exact-context is only valid in a provider scheme or exact provider argument"
      parseGoalSexp
          ("(goal type (query (roots \"Gap\") (head)) "
            ++ contextual ++ ")")
        @?= expected
      parseProviderSexp
          ("(providers (provider \"Gap.conditional\" (binders \"a\") "
            ++ "(alli \"a\" (exact-context \"Gap.C\" (arguments "
            ++ "(kinded 0 (var \"a\"))) "
            ++ "(atom unsafe \"Gap.Token\")))))")
        @?= Right
          [ ProviderFragWithBinders "Gap.conditional"
              (FAll False "a"
                (FExactContext "Gap.C"
                  [ExactContextFragmentArgument 0 (FVar "a")]
                  (FAtom False "Gap.Token")))
              ["a"]
          ]
      parseProviderSexp
          ("(providers (provider \"Gap.global\" (binders \"a\") "
            ++ "(instantiations (args (kinded 0 " ++ contextual ++ "))) "
            ++ "(alli \"a\" (atom unsafe \"Gap.Token\"))))")
        @?= expected
      parseProviderSexp
          ("(providers (provider \"Gap.global\" (binders \"a\") "
            ++ "(instantiations (args (kinded 0 (nominal \"Gap.Wrap\" "
            ++ contextual ++ ")))) "
            ++ "(alli \"a\" (atom unsafe \"Gap.Token\"))))")
        @?= expected
  , testCase "validate bound higher-kinded provider context variables" $ do
      let token = FAtom False "Gap.Token"
          natural = FAtom False "Nat"
          context = FExactContext "Gap.HigherC"
            [ExactContextFragmentArgument 1 $ FVar "F"] token
          bound = FAll False "F" context
          partialContext = FExactContext "Gap.HigherC"
            [ ExactContextFragmentArgument 1 $
                FApp True "F a" (AppVariable "F") [FVar "a"]
            ]
            token
          partialBound = FAll False "F" $ FAll False "a" partialContext
          contextWire =
            "(exact-context \"Gap.HigherC\" (arguments "
              ++ "(kinded 1 (var \"F\"))) "
              ++ "(atom unsafe \"Gap.Token\"))"
          partialContextWire =
            "(exact-context \"Gap.HigherC\" (arguments "
              ++ "(kinded 1 (app safe \"F a\" "
              ++ "(app-variable \"F\") (var \"a\")))) "
              ++ "(atom unsafe \"Gap.Token\"))"
          inventory name body =
            "(providers (provider \"" ++ name
              ++ "\" (binders \"F\") " ++ body ++ "))"
          partialInventory name body =
            "(providers (provider \"" ++ name
              ++ "\" (binders \"F\" \"a\") " ++ body ++ "))"
      parseProviderSexp
          (inventory "Gap.boundHigher" $ "(alli \"F\" "
            ++ contextWire ++ ")") @?=
        Right
          [ ProviderFragWithBinders "Gap.boundHigher" bound ["F"] ]
      fragHasInstanceBinder bound @?= True
      fragHasUnsupportedInstanceBinder bound @?= False
      parseProviderSexp (inventory "Gap.openHigher" contextWire) @?=
        Right
          [ ProviderFragWithBinders "Gap.openHigher" context ["F"] ]
      fragHasInstanceBinder context @?= True
      fragHasUnsupportedInstanceBinder context @?= True
      parseProviderSexp
          (partialInventory "Gap.boundPartial" $
            "(alli \"F\" (alli \"a\" " ++ partialContextWire ++ "))") @?=
        Right
          [ ProviderFragWithBinders "Gap.boundPartial" partialBound ["F", "a"] ]
      fragHasUnsupportedInstanceBinder partialBound @?= False
      fragHasUnsupportedInstanceBinder
        (FAll False "a" partialContext) @?= True
      fragHasUnsupportedInstanceBinder
        (FAll False "F" partialContext) @?= True
      fragHasUnsupportedInstanceBinder
        (FAll False "F" $ FAll False "a" $
          FExactContext "Gap.HigherC"
            [ ExactContextFragmentArgument 1 $
                FApp True "F Nat" (AppVariable "F") [natural]
            ]
            (FArr (FVar "F") token)) @?= True
  , testCase "retain a general Sort provider forall domain" $
      parseProviderSexp
          ("(providers (provider \"Gap.sort\" (binders \"a\") "
            ++ "(instantiations (args (kinded 0 (exact (domains sort) "
            ++ "(alli \"A\" (var \"A\")))))) "
            ++ "(alli \"a\" (atom unsafe \"Gap.Token\"))))")
        @?= Right
          [ ProviderFragWithEvidence "Gap.sort"
              (FAll False "a" (FAtom False "Gap.Token"))
              ["a"]
              [ [ ProviderInstantiationExactArgument 0
                    (FAll False "A" (FVar "A"))
                    [ProviderForallDomainSort]
                ]
              ]
          ]
  , testCase "reject invalid exact Lean provider forall domains" $ do
      let inventory domains =
            "(providers (provider \"Gap.global\" (binders \"a\") "
              ++ "(instantiations (args (kinded 0 (exact (domains "
              ++ domains
              ++ ") (atom unsafe \"Nat\"))))) "
              ++ "(alli \"a\" (atom unsafe \"Gap.Token\"))))"
      parseProviderSexp (inventory "effect") @?=
        Left "unknown exact Lean provider forall-domain tag"
      parseProviderSexp (inventory "prop") @?=
        Left "exact Lean provider forall-domain vector does not align with its fragment"
      parseProviderSexp
          ("(providers (provider \"Gap.global\" (binders \"a\") "
            ++ "(instantiations (args (kinded 0 (exact (domains \"prop\") "
            ++ "(atom unsafe \"Nat\"))))) "
            ++ "(alli \"a\" (atom unsafe \"Gap.Token\"))))") @?=
        Left "malformed exact Lean provider forall-domain vector"
      parseProviderSexp
          (inventory $ unwords $
            replicate (maximumProviderExactForallDomains + 1) "prop")
        @?= Left "exact Lean provider forall-domain vector is too long"
  , testCase "bound structured exact-context class arguments" $ do
      let inventory arguments =
            "(providers (provider \"Gap.global\" (binders \"a\") "
              ++ "(instantiations (args (kinded 0 (exact (domains) "
              ++ "(exact-context \"Gap.C\" (arguments " ++ arguments
              ++ ") (atom unsafe \"Nat\")))))) "
              ++ "(alli \"a\" (atom unsafe \"Gap.Token\"))))"
          proper = "(kinded 0 (atom unsafe \"Nat\"))"
      parseProviderSexp (inventory
          "(kinded 65 (atom unsafe \"Nat\"))")
        @?= Left "invalid exact-context class argument kind arity"
      parseProviderSexp (inventory $ unwords $
          replicate (maximumProviderInstantiationArguments + 1) proper)
        @?= Left "too many exact-context class arguments"
  , testCase "retain canonical nominal provider arguments" $
      parseProviderSexp
          "(providers (provider \"Gap.partial\" (binders \"F\") \
          \(instantiations (args \
          \(kinded 1 (nominal \"Gap.Pair\" \
          \(atom unsafe \"Nat\"))))) \
          \(alli \"F\" (-> \
          \(app unsafe \"F Bool\" (app-variable \"F\") \
          \(atom unsafe \"Bool\")) \
          \(atom unsafe \"Gap.Token\")))))"
        @?= Right
          [ ProviderFragWithEvidence "Gap.partial"
              (FAll False "F"
                (FArr
                  (FApp False "F Bool" (AppVariable "F")
                    [FAtom False "Bool"])
                  (FAtom False "Gap.Token")))
              ["F"]
              [ [ ProviderInstantiationNominalArgument 1 "Gap.Pair"
                    [FAtom False "Nat"]
                ]
              ]
          ]
  , testCase "retain residual binary provider argument kinds" $
      parseProviderSexp
          "(providers (provider \"Gap.vacuous\" (binders \"F\") \
          \(instantiations (args \
          \(kinded 2 (nominal \"Gap.Triple\" \
          \(atom unsafe \"Nat\"))))) \
          \(alli \"F\" (atom unsafe \"Gap.Token\"))))"
        @?= Right
          [ ProviderFragWithEvidence "Gap.vacuous"
              (FAll False "F" (FAtom False "Gap.Token"))
              ["F"]
              [ [ ProviderInstantiationNominalArgument 2 "Gap.Triple"
                    [FAtom False "Nat"]
                ]
              ]
          ]
  , testCase "reject invalid provider argument kinds" $ do
      let inventory arity =
            "(providers (provider \"Gap.global\" (binders \"F\") "
              ++ "(instantiations (args (kinded " ++ arity
              ++ " (atom unsafe \"Gap.Wrap\")))) "
              ++ "(alli \"F\" (atom unsafe \"Gap.Token\"))))"
          rejected arity = case parseProviderSexp (inventory arity) of
            Left "invalid provider instantiation argument kind arity" ->
              pure ()
            other -> assertFailure $
              "accepted invalid provider kind " ++ arity ++ ": " ++ show other
          accepted arity = case parseProviderSexp (inventory arity) of
            Right _ -> pure ()
            other -> assertFailure $
              "rejected valid provider kind " ++ arity ++ ": " ++ show other
      maximumProviderArgumentKindArity @?= 64
      maximumProviderArgumentKindArity @?=
        (maximumProviderInstantiationKindNodes - 1) `div` 2
      accepted "64"
      mapM_ rejected ["-1", "65", "not-a-kind"]
  , testCase "distinguish an explicit empty evidence block" $
      parseProviderSexp
          "(providers (provider \"Gap.token\" (binders) (candidates) \
          \(atom unsafe \"Gap.Token\")))"
        @?= Right
          [ ProviderFragWithLegacyCandidates "Gap.token"
              (FAtom False "Gap.Token") [] []
          ]
  , testCase "accept an explicit empty exact-instantiation block" $
      parseProviderSexp
          "(providers (provider \"Gap.token\" (binders) (instantiations) \
          \(atom unsafe \"Gap.Token\")))"
        @?= Right
          [ ProviderFragWithEvidence "Gap.token"
              (FAtom False "Gap.Token") [] []
          ]
  , testCase "reject an empty exact argument vector" $
      parseProviderSexp
          "(providers (provider \"Gap.bad\" (binders \"a\") \
          \(instantiations (args)) \
          \(alli \"a\" (atom unsafe \"Gap.Token\"))))"
        @?= Left "provider instantiation assignment has no arguments"
  , testCase "retain legacy contextual evidence for fail-closed filtering" $
      let contextual = FAll False "a"
            (FInst "Inhabited a" (FVar "a"))
      in do
        parseProviderSexp
            "(providers (provider \"Gap.global\" (binders \"a\") \
            \(candidates (alli \"a\" \
            \(inst \"Inhabited a\" (var \"a\")))) \
            \(alli \"a\" (atom unsafe \"Gap.Token\"))))"
          @?= Right
            [ ProviderFragWithLegacyCandidates "Gap.global"
                (FAll False "a" (FAtom False "Gap.Token"))
                ["a"] [contextual]
            ]
        fragHasInstanceBinder contextual @?= True
        fragHasUnsupportedInstanceBinder contextual @?= True
        fragHasInstanceBinder
          (FAll True "a" (FArr (FVar "a") (FVar "a"))) @?= False
  , testCase "rejects trailing inventory data" $
      parseProviderSexp "(providers) extra" @?=
        Left "trailing tokens in provider translation"
  ]

instanceImplicitTests :: TestTree
instanceImplicitTests = testGroup "instance-implicit synthesis"
  [ testCase "parse a render-only instance binder distinctly" $ do
      let body = FAll True "A"
            (FInst "Gap.C A" (FArr (FVar "A") (FVar "A")))
      parseGoalSexp
          "(goal type (query (roots \"Gap\") (head)) \
          \(all \"A\" (inst \"Gap.C A\" (-> (var \"A\") (var \"A\")))))"
        @?= Right (ParsedGoal GoalType
          (ProviderQuery ["Gap"] Nothing) body [])
      fragUnsafeAtoms body @?= ["Gap.C A"]
  , testCase "bind an erased instance before ordinary term arguments" $ do
      let goal = FAll True "A"
            (FInst "Gap.C A" (FArr (FVar "A") (FVar "A")))
          check engine =
            expectInstanceTerm "fun _ _ x => x"
              (synthesizeWithProviders engine 4096 [] goal)
      mapM_ check [EngineDjinn, EngineExference, EngineBoth]
  , testCase "reconstruct evidence for a constrained rank-N hypothesis" $ do
      let goal = FAll True "A" (FAll True "R"
            (FInst "Gap.C A"
              (FArr
                (FAll True "a"
                  (FInst "Gap.C a" (FArr (FVar "a") (FVar "R"))))
                (FArr (FVar "A") (FVar "R")))))
          check engine =
            expectInstanceTerm "fun _ _ _ f => f _"
              (synthesizeWithProviders engine 4096 [] goal)
      mapM_ check [EngineDjinn, EngineExference, EngineBoth]
  , testCase "withhold a refutation after erasing dictionary evidence" $ do
      let impossible = FAll True "A" (FInst "Gap.C A" FBot)
      case synthesizeWithProviders EngineDjinn 0 [] impossible of
        Right (SynthRefuted False) -> pure ()
        Right other -> assertFailure $
          "erased instance evidence produced the wrong verdict: "
            ++ outcomeTag other
        Left err -> assertFailure err
  ]
 where
  expectInstanceTerm expected outcome = case outcome of
    Right (SynthCandidates groups _) ->
      if any (== expected) (concat groups)
        then pure ()
        else assertFailure $
          "expected instance-aware candidate " ++ show expected
            ++ ", got: " ++ show groups
    Right other -> assertFailure $
      "unexpected instance-aware outcome: " ++ outcomeTag other
    Left err -> assertFailure err

providerScheduleTests :: TestTree
providerScheduleTests = testGroup "live provider widening"
  [ testCase "keep Exference on one rated full-inventory lane" $
      providerStages EngineExference ([1 .. 80] :: [Int]) @?=
        [(EngineExference, [1 .. 80])]
  , testCase "widen Djinn through sparse discovery-order prefixes" $
      providerStages EngineDjinn ([1 .. 80] :: [Int]) @?=
        [ (EngineDjinn, [1])
        , (EngineDjinn, [1 .. 4])
        , (EngineDjinn, [1 .. 16])
        , (EngineDjinn, [1 .. 80])
        ]
  , testCase "run only intermediate combined prefixes through Djinn" $
      providerStages EngineBoth ([1 .. 17] :: [Int]) @?=
        [ (EngineBoth, [1])
        , (EngineDjinn, [1 .. 4])
        , (EngineDjinn, [1 .. 16])
        , (EngineBoth, [1 .. 17])
        ]
  , testCase "deduplicate milestones at short inventory boundaries" $ do
      let inventory size = [1 .. size] :: [Int]
      providerStages EngineDjinn (inventory 0) @?= []
      providerStages EngineDjinn (inventory 1) @?= [(EngineDjinn, [1])]
      providerStages EngineDjinn (inventory 2) @?=
        [(EngineDjinn, [1]), (EngineDjinn, [1, 2])]
      providerStages EngineDjinn (inventory 4) @?=
        [(EngineDjinn, [1]), (EngineDjinn, [1 .. 4])]
      providerStages EngineBoth (inventory 1) @?=
        [(EngineBoth, [1])]
      providerStages EngineBoth (inventory 2) @?=
        [(EngineBoth, [1]), (EngineBoth, [1, 2])]
      providerStages EngineBoth (inventory 5) @?=
        [ (EngineBoth, [1])
        , (EngineDjinn, [1 .. 4])
        , (EngineBoth, [1 .. 5])
        ]
  ]

combinedEngineMergeTests :: TestTree
combinedEngineMergeTests = testGroup "combined-engine verification frontier"
  [ testCase "deduplicate before spending the candidate window" $
      takeDistinct 3
          (replicate 60 "same" ++ ["later", "last", "outside"])
        @?= ["same", "later", "last"]
  , testCase "reserve a bounded frontier for fresh Exference groups" $ do
      let groups prefix = [[prefix ++ show i] | i <- [1 :: Int .. 20]]
          merged = mergeCandidateGroups (groups "d") (groups "e")
      synthVerificationWindow EngineDjinn @?= synthMaxTried
      synthVerificationWindow EngineExference @?= synthMaxTried
      synthVerificationWindow EngineBoth @?= 2 * synthMaxTried
      take (synthVerificationWindow EngineBoth) merged @?=
        map (\i -> ["d" ++ show i]) [1 :: Int .. 4]
          ++ map (\i -> ["e" ++ show i]) [1 :: Int .. 12]
          ++ map (\i -> ["d" ++ show i]) [5 :: Int .. 12]
      take synthMaxShown merged @?=
        [["d1"], ["d2"], ["d3"], ["d4"], ["e1"]]
      merged !! (synthMaxTried - 1) @?= ["e8"]
      take 4 (drop (synthVerificationWindow EngineBoth) merged) @?=
        [["e13"], ["d13"], ["e14"], ["d14"]]
  , testCase "surface an oldest-first constrained choice in the shown frontier" $ do
      let token = FAtom False "Demo.Token"
          finite name = FParamInd name name [] [(name ++ ".mk", [])]
          inputs =
            [finite ("Demo.A" ++ show i) | i <- [1 :: Int .. 7]]
              ++ [finite "Demo.Good"]
          goal = foldr FArr token inputs
          provider = ProviderFragWithBinders "Demo.global"
            (FAll False "a" token) ["a"]
          isGood = any (isInfixOf "Demo.global (\171a\187 := Demo.Good)")
      case synthesizeWithProviders EngineBoth 1 [provider] goal of
        Right (SynthCandidates groups _) -> do
          any isGood (take (synthMaxShown - 1) groups) @?= False
          any isGood (take synthMaxShown groups) @?= True
        Right other -> assertFailure $
          "expected combined candidates, got: " ++ outcomeTag other
        Left err -> assertFailure err
  , testCase "drain either ranked lane without losing its order" $ do
      mergeCandidateGroups [["d1"], ["d2"]]
          [["e1"], ["e2"], ["e3"]]
        @?= [["d1"], ["d2"], ["e1"], ["e2"], ["e3"]]
      mergeCandidateGroups [] [["e1"], ["e2"]]
        @?= [["e1"], ["e2"]]
      mergeCandidateGroups [["d1"], ["d2"]] []
        @?= [["d1"], ["d2"]]
  , testCase "deduplicate variants in final scheduled order" $ do
      mergeCandidateGroups
          [ ["d1", "d1", "d1-alt"]
          , []
          , ["d1-alt"]
          , ["d2"]
          , ["shared"]
          ]
          [["shared", "e1-alt"], ["d2", "e2"]]
        @?=
          [ ["d1", "d1-alt"]
          , ["d2"]
          , ["shared"]
          , ["e1-alt"]
          , ["e2"]
          ]
  , testCase "let early Exference spellings outrank late Djinn duplicates" $
      mergeCandidateGroups
          ( [ ["d1"], ["d2"], ["d3"], ["d4"] ]
          ++ [ ["d" ++ show i] | i <- [5 :: Int .. 12] ]
          ++ [ ["shared", "d-alt"] ]
          )
          [["shared", "e-alt"]]
        @?=
          ( [ ["d1"], ["d2"], ["d3"], ["d4"]
            , ["shared", "e-alt"]
            ]
          ++ [ ["d" ++ show i] | i <- [5 :: Int .. 12] ]
          ++ [["d-alt"]]
          )
  , testCase "remove checked spellings before spending a fresh lane quota" $ do
      let checked = Set.fromList ["old" ++ show i | i <- [1 :: Int .. 20]]
          groups = [["old" ++ show i] | i <- [1 :: Int .. 20]]
            ++ [["fresh", "old1"], ["later"]]
      withoutCheckedCandidates checked (SynthCandidates groups ["ranked"])
        @?= SynthCandidates [["fresh"], ["later"]] ["ranked"]
      withoutCheckedCandidates (Set.singleton "only")
          (SynthCandidates [["only"], []] ["empty"])
        @?= SynthNoTerm ["empty"]
  , testCase "reserve source-local quotas after checked-lane filtering" $ do
      let groups prefix count =
            [[prefix ++ show i] | i <- [1 :: Int .. count]]
          checked = Set.fromList ["e" ++ show i | i <- [1 :: Int .. 12]]
          merged = mergeOutcomesSkipping checked
            (SynthCandidates (groups "d" 30) [])
            (SynthCandidates (groups "e" 24) [])
      case merged of
        SynthCandidates candidateGroups _ ->
          take (synthVerificationWindow EngineBoth) candidateGroups @?=
            groups "d" 4
              ++ [["e" ++ show i] | i <- [13 :: Int .. 24]]
              ++ [["d" ++ show i] | i <- [5 :: Int .. 12]]
        other -> assertFailure $
          "expected filtered combined candidates, got: " ++ outcomeTag other
  , testCase "normalize empty rendered candidates without inventing evidence" $ do
      mergeOutcomes
          (SynthCandidates [[], []] ["djinn empty"])
          (SynthNoTerm ["exference empty"])
        @?= SynthNoTerm
          ["djinn empty", "exference: exference empty"]
      mergeOutcomes
          (SynthCandidates [] ["djinn empty"])
          (SynthCandidates [["e1"]] ["ranked"])
        @?= SynthCandidates [["e1"]]
          ["djinn empty", "exference: ranked"]
  , testCase "preserve Djinn refutations unless a real candidate wins" $ do
      mergeOutcomes (SynthRefuted True)
          (SynthCandidates [[]] ["empty"])
        @?= SynthRefuted True
      mergeOutcomes (SynthRefuted False) (SynthNoTerm ["none"])
        @?= SynthRefuted False
      mergeOutcomes (SynthRefuted True)
          (SynthCandidates [["e1"]] ["ranked"])
        @?= SynthCandidates [["e1"]] ["exference: ranked"]
  , testCase "retain note provenance for every candidate-bearing merge" $ do
      mergeOutcomes
          (SynthCandidates [["d1"]] ["smallest"])
          (SynthCandidates [["e1"]] ["rated"])
        @?= SynthCandidates [["d1"], ["e1"]]
          ["smallest", "exference: rated"]
      mergeOutcomes
          (SynthCandidates [["d1"]] ["smallest"])
          (SynthNoTerm ["finished"])
        @?= SynthCandidates [["d1"]]
          ["smallest", "exference: finished"]
      mergeOutcomes
          (SynthNoTerm ["bounded"])
          (SynthCandidates [["e1"]] ["rated"])
        @?= SynthCandidates [["e1"]]
          ["bounded", "exference: rated"]
  ]

lengthSpinePairBoundaryTests :: TestTree
lengthSpinePairBoundaryTests = testGroup
  "canonical Lean Prod Length handoff"
  [ testCase
      "emit and parse a provenance marker only for saturated canonical Prod" $
      do
        let prelude = synthPrelude []
            canonicalBranch = unlines
              [ "        else if args.size == 2 && n == ``Prod then"
              , "          bin \"lean-prod\""
              ]
            structuralBranch = unlines
              [ "        else if args.size == 2 &&"
              , "            (n == ``And || n == ``PProd) then"
              , "          bin \"prod\""
              ]
            wire tag =
              "(goal type (query (roots \"Prod\") (head \"Prod\")) ("
                ++ tag
                ++ " (atom unsafe \"Nat\") (atom unsafe \"Bool\")))"
            parsed fragment = Right $ ParsedGoal GoalType
              (ProviderQuery ["Prod"] $ Just "Prod") fragment []
        assertBool "canonical saturated Prod lost its exact wire marker"
          $ canonicalBranch `isInfixOf` prelude
        assertBool "And/PProd stopped sharing the structural pair wire"
          $ structuralBranch `isInfixOf` prelude
        parseGoalSexp (wire "lean-prod") @?= parsed
          (FLeanProd (FAtom False "Nat") (FAtom False "Bool"))
        parseGoalSexp (wire "prod") @?= parsed
          (FProd (FAtom False "Nat") (FAtom False "Bool"))
  , testCase
      "preserve exact Prod through rendering/search without inventing a family" $
      do
        let token = FAtom False "Nat"
            renderGoal = FArr token $ FLeanProd token token
            expression = Lambda [Bind "x"]
              $ Tuple [Local "x", Local "x"]
            goal = lengthSpinePairFixtureGoal
        renderLeanTerm Map.empty Map.empty Map.empty ([], 0, [])
            renderGoal expression @?= Right ["fun x => \10216x, x\10217"]
        preparation <- expectRight
          $ inspectExferencePreparation [] [] goal goal
        inspectedEngineFragment preparation @?= goal
        inspectedFitFragment preparation @?= goal
        map inspectedSemanticFamilyLeanName
            (inspectedSemanticFamilyBindings preparation) @?= ["List"]
        assertBool "canonical Prod acquired fabricated semantic-family authority"
          $ all ((/= "Prod") . inspectedSemanticFamilyLeanName)
          $ inspectedSemanticFamilyBindings preparation
  , testCase
      "seal an input-only product query and replay pair-domain evidence" $ do
        verified <- verifiedFirstDirectTypedCandidate
          lengthSpinePairFixtureGoal
        problem <- expectRight $ prepareCheckedLengthSpinePairProblem
          lengthSpinePairFixtureContract verified
        query <- expectRight
            (prepareCheckedLengthSpinePairQuery
              lengthSpinePairFixtureContract verified)
          >>= expectRight
        let inputSymbol = spinePairBytes "djex_length_input_0"
            behavioral =
              Djex.lengthSpinePairSMTLibQueryBehavioralProblem query
            checkText = map (toEnum . fromIntegral)
              $ Djex.lengthSpinePairSMTLibQueryCheckBytes query
        Djex.lengthSpinePairSMTLibQueryInputSymbols query @?= [inputSymbol]
        Djex.lengthSpinePairSMTLibQueryInputValueRequestBytes query @?=
          Just (spinePairBytes "(get-value (djex_length_input_0))\n")
        assertBool "product check command exposed a result binding"
          $ not $ "djex_length_result" `isInfixOf` checkText
        Djex.behavioralProblemDomain behavioral @?=
          Djex.finiteBinaryProductSpineLengthsDomainTag
        assertBool "product query reused the scalar behavioral domain"
          $ Djex.behavioralProblemDomain behavioral /=
              Djex.finiteListSpineLengthDomainTag
        behavioralProblemFingerprint behavioral @?=
          behavioralProblemFingerprint
            (Djex.checkedLengthSpinePairProblemBehavioralProblem problem)
        evidence <- case Djex.validateLengthSpinePairSMTLibCounterexample
            defaultLengthEvaluationLimits query
            [Djex.LengthSMTLibIntegerBinding inputSymbol 2] of
          Left failure -> assertFailure
            ("product model replay failed: " ++ show failure)
              >> error "unreachable"
          Right Nothing -> assertFailure
            "the violating product model produced no evidence"
              >> error "unreachable"
          Right (Just retained) -> pure retained
        receipt <- expectRight $ Djex.replayBehavioralEvidence behavioral evidence
        Djex.validatedLengthSpinePairCounterexampleInputs receipt @?= [2]
        Djex.validatedLengthSpinePairCounterexampleResult receipt @?=
          Djex.LengthSpinePair 2 2
        Djex.validatedLengthSpinePairCounterexampleBasis receipt @?=
          Djex.ProviderIndependentFiniteSpineModel
  , testCase
      "reject scalar, structural, nested, nonspine, and wrong-family results" $
      do
        scalarVerified <- verifiedFirstDirectTypedCandidate
          $ FArr lengthSpinePairFixtureList lengthSpinePairFixtureList
        scalarProblem <- expectRight $ prepareCheckedLengthProblem
          lengthSpinePairScalarRegressionContract scalarVerified
        scalarQuery <- expectRight
            (prepareCheckedLengthQuery
              lengthSpinePairScalarRegressionContract scalarVerified)
          >>= expectRight
        lengthSMTLibQuerySchemaTag @?=
          spinePairBytes "djex-length-z3-qf-lia-smtlib2/v2"
        lengthSMTLibQueryInputSymbols scalarQuery @?=
          [spinePairBytes "djex_length_input_0"]
        behavioralProblemFingerprint
            (lengthSMTLibQueryBehavioralProblem scalarQuery) @?=
          behavioralProblemFingerprint
            (checkedLengthProblemBehavioralProblem scalarProblem)
        assertLengthSpinePairRefusal "scalar result"
          LengthSpinePairHandoffResultNotCanonicalLeanProd
          lengthSpinePairFixtureContract scalarVerified

        structuralVerified <- verifiedFirstDirectTypedCandidate
          $ FArr lengthSpinePairFixtureList
          $ FProd lengthSpinePairFixtureList lengthSpinePairFixtureList
        assertLengthSpinePairRefusal "And/PProd structural result"
          LengthSpinePairHandoffResultNotCanonicalLeanProd
          lengthSpinePairFixtureContract structuralVerified
        case prepareCheckedLengthSpinePairQueryWithLimits
            (error "structural refusal forced product query limits")
            lengthSpinePairFixtureContract structuralVerified of
          Left refusal -> refusal @?=
            LengthSpinePairHandoffResultNotCanonicalLeanProd
          Right _ -> assertFailure
            "a structural And/PProd result reached product query sealing"

        nestedVerified <- verifiedFirstDirectTypedCandidate
          $ FArr lengthSpinePairFixtureList
          $ FLeanProd lengthSpinePairFixtureList
          $ FLeanProd lengthSpinePairFixtureList lengthSpinePairFixtureList
        assertLengthSpinePairRefusal "nested/nonbinary product result"
          (LengthSpinePairHandoffComponentNotConfiguredSpine
            Djex.LengthSpinePairSecond "List")
          lengthSpinePairFixtureContract nestedVerified

        nonspineVerified <- verifiedFirstDirectTypedCandidate
          $ FArr lengthSpinePairFixtureList
          $ FLeanProd lengthSpinePairFixtureList FTop
        assertLengthSpinePairRefusal "nonspine product component"
          (LengthSpinePairHandoffComponentNotConfiguredSpine
            Djex.LengthSpinePairSecond "List")
          lengthSpinePairFixtureContract nonspineVerified

        pairVerified <- verifiedFirstDirectTypedCandidate
          lengthSpinePairFixtureGoal
        let wrongFamily = lengthSpinePairFixtureContract
              { leanLengthSpinePairContractSpine =
                  (leanLengthSpinePairContractSpine
                    lengthSpinePairFixtureContract)
                    { leanLengthSpineFamilyName = "Wrong.List" }
              }
        assertLengthSpinePairRefusal "wrong configured family"
          (LengthSpinePairHandoffComponentNotConfiguredSpine
            Djex.LengthSpinePairFirst "Wrong.List")
          wrongFamily pairVerified
  ]

lengthSpinePairFixtureList :: Frag
lengthSpinePairFixtureList = FParamRec True "List" listKey [natural]
  [ ("List.nil", [])
  , ("List.cons", [natural, FAtom False listKey])
  ]
 where
  natural = FAtom False "Nat"
  listKey = "List Nat"

lengthSpinePairFixtureGoal :: Frag
lengthSpinePairFixtureGoal = FArr lengthSpinePairFixtureList
  $ FLeanProd lengthSpinePairFixtureList lengthSpinePairFixtureList

lengthSpinePairFixtureSpine :: LeanLengthSpineIdentity
lengthSpinePairFixtureSpine = LeanLengthSpineIdentity
  { leanLengthSpineFamilyName = "List"
  , leanLengthSpineZeroConstructorName = "List.nil"
  , leanLengthSpineStepConstructorName = "List.cons"
  }

lengthSpinePairFixtureContract :: LeanLengthSpinePairContract
lengthSpinePairFixtureContract = LeanLengthSpinePairContract
  { leanLengthSpinePairContractSpine = lengthSpinePairFixtureSpine
  , leanLengthSpinePairContractTargetArgumentRoles = Nothing
  , leanLengthSpinePairContractCandidateCasePolicy = LeanLengthCasesRejected
  , leanLengthSpinePairContractSource = Djex.LengthSpinePairContractSource
      { Djex.lengthSpinePairContractPrecondition = Djex.LengthTruth True
      , Djex.lengthSpinePairContractPostcondition = Djex.LengthAll
          [ Djex.LengthEqual
              (Djex.LengthVariable $ Djex.LengthSpinePairResult
                Djex.LengthSpinePairFirst)
              (Djex.LengthVariable $ Djex.LengthSpinePairInput 0)
          , Djex.LengthEqual
              (Djex.LengthVariable $ Djex.LengthSpinePairResult
                Djex.LengthSpinePairSecond)
              (Djex.LengthLiteral 0)
          ]
      }
  , leanLengthSpinePairContractProviderLaws = []
  }

lengthSpinePairScalarRegressionContract :: LeanLengthContract
lengthSpinePairScalarRegressionContract = LeanLengthContract
  { leanLengthContractSpine = lengthSpinePairFixtureSpine
  , leanLengthContractTargetArgumentRoles = Nothing
  , leanLengthContractCandidateCasePolicy = LeanLengthCasesRejected
  , leanLengthContractSource = LengthContractSource
      { lengthContractPrecondition = LengthTruth True
      , lengthContractPostcondition = LengthTruth True
      }
  , leanLengthContractProviderLaws = []
  }

verifiedFirstDirectTypedCandidate
  :: Frag
  -> IO (Verified DetailedVerificationVariant)
verifiedFirstDirectTypedCandidate goal = do
  detailed <- expectRight $
    synthesizeWithProvidersSkippingDetailedWithMultiConstructorPatterns
      False EngineExference 512 Set.empty [] goal
  group <- case detailed of
    DetailedSynthCandidates groups _ -> case
        [ retained
        | retained <- groups
        , detailedCandidateGroupRoute retained == RouteTypedCandidate
        , not $ isNothing $ detailedCandidateGroupSemanticSidecar retained
        , [_] <- [detailedCandidateGroupVariants retained]
        ] of
      retained : _ -> pure retained
      [] -> assertFailure
        ("fixture produced no singleton exact typed candidate: "
          ++ show (map detailedCandidateGroupVariants groups))
          >> error "unreachable"
    other -> assertFailure
      ("fixture synthesis failed: " ++ show other) >> error "unreachable"
  batch <- verifyCandidateGroups 1 (const $ pure VariantAccepted)
    [detailedCandidateGroupVerificationVariants group]
  case verifiedCandidateReceipts batch of
    [verified] -> pure verified
    receipts -> assertFailure
      ("fixture verification produced " ++ show (length receipts)
        ++ " receipts") >> error "unreachable"

assertLengthSpinePairRefusal
  :: String
  -> LengthSpinePairHandoffRefusal
  -> LeanLengthSpinePairContract
  -> Verified DetailedVerificationVariant
  -> IO ()
assertLengthSpinePairRefusal label expected contract verified =
  case prepareCheckedLengthSpinePairProblem contract verified of
    Left refusal -> refusal @?= expected
    Right _ -> assertFailure $ label
      ++ " acquired a checked binary-product problem"

spinePairBytes :: String -> [Word8]
spinePairBytes = map $ fromIntegral . fromEnum

lengthSpinePairRankingTests :: TestTree
lengthSpinePairRankingTests = testGroup
  "canonical Prod live Length ranking"
  [ testCase "avoid a session when no exact product candidate is eligible"
      assertLengthSpinePairRankingNoSession
  , testCase "keep pair sat, unsat, and unknown statuses heuristic"
      assertLengthSpinePairRankingNeutralStatuses
  , testCase
      "demote exact pair counterexamples and keep a four-vector fresh MRU"
      assertLengthSpinePairRankingCounterexamples
  , testCase "probe a pair origin before assigning a compact live ordinal"
      assertLengthSpinePairRankingOriginOrdering
  , testCase "exercise every enabled pair policy branch through Configuration"
      assertLengthSpinePairRankingPolicyBranches
  , testCase
      "use pair unsat only to trigger independent finite-box validation"
      assertLengthSpinePairRankingInputBox
  , testCase
      "establish and present directly bounded pair domains before Z3"
      assertLengthSpinePairApplicableDomain
  , testCase
      "prefer non-vacuous pair positives after unchanged serial assessment"
      assertLengthSpinePairNonVacuousPositivePreference
  , testCase
      "keep vacuous pair positives neutral and preserve fallback associations"
      assertLengthSpinePairPositivePreferenceSafety
  , testCase
      "seal duplicate pair occurrences and present both result components"
      assertLengthSpinePairPostVerificationPresentation
  , testCase "atomically reset pair live, session, and box failures"
      assertLengthSpinePairRankingAtomicFailures
  , testCase "leave scalar query bytes and terminal wording unchanged"
      assertLengthSpinePairScalarRegression
  ]

assertLengthSpinePairRankingNoSession :: IO ()
assertLengthSpinePairRankingNoSession = do
  refused <- syntheticLengthRankingCandidate "pair-no-session-refusal"
  result <- rankVerifiedLengthSpinePairCandidates
    (error "ineligible product ranking opened a solver session")
    defaultLengthEvaluationLimits
    (error "ineligible product ranking forced its contract") [refused]
  ranking <- expectRight result
  lengthSpinePairRankingFailure ranking @?= Nothing
  rankedLengthSpinePairVerifiedCandidates ranking @?= [refused]
  map rankedLengthSpinePairCandidateAssessment
      (lengthSpinePairRankingCandidates ranking) @?=
    [LengthSpinePairUnassessed]
  rankedLengthSpinePairPreparationRefusals ranking @?=
    [Just LengthPreparationTypedAuthorityUnavailable]

  let maximumCandidates =
        Djex.defaultLengthSMTLibLiveSessionMaximumQueries
      exact = replicate (fromIntegral maximumCandidates) refused
      unopened = error "bounded product admission opened a solver session"
      unprepared = error "bounded product admission forced its contract"
  exactResult <- rankVerifiedLengthSpinePairCandidates unopened
    defaultLengthEvaluationLimits unprepared exact
  exactRanking <- expectRight exactResult
  length (lengthSpinePairRankingCandidates exactRanking) @?=
    fromIntegral maximumCandidates
  bounded <- timeout 1000000
    $ rankVerifiedLengthSpinePairCandidates unopened
        defaultLengthEvaluationLimits unprepared $ repeat refused
  case bounded of
    Just (Left (LengthRankingInputLimitExceeded retainedMaximum observed)) -> do
      retainedMaximum @?= maximumCandidates
      observed @?= maximumCandidates + 1
    Just (Right _) -> assertFailure
      "cyclic product maximum-plus-one input was admitted"
    Nothing -> assertFailure
      "cyclic product maximum-plus-one input was not rejected productively"

assertLengthSpinePairRankingNeutralStatuses :: IO ()
assertLengthSpinePairRankingNeutralStatuses = do
  (duplicatedInput, _) <- buildLengthSpinePairRankingFixture
  let cases =
        [ ( "healthy"
          , Djex.LengthSMTLibStatusOnly
          , Djex.SolverSatisfiable
          )
        , ( "query-unsat"
          , Djex.LengthSMTLibInputValuesAfterSatisfiable
          , Djex.SolverUnsatisfiable
          )
        , ( "query-unknown"
          , Djex.LengthSMTLibInputValuesAfterSatisfiable
          , Djex.SolverUnknown
          )
        ]
  mapM_ (assertStatus duplicatedInput) cases
 where
  assertStatus candidate (mode, policy, expected) = do
    (ranking, events) <- runLengthSpinePairRankingWithFakeTrace
      mode policy defaultLengthEvaluationLimits
      lengthSpinePairRankingContract [candidate]
    lengthSpinePairRankingFailure ranking @?= Nothing
    map rankedLengthSpinePairCandidateAssessment
        (lengthSpinePairRankingCandidates ranking) @?=
      [LengthSpinePairHeuristic expected]
    assertFakeLengthQueryEvents [0] [] events

assertLengthSpinePairRankingCounterexamples :: IO ()
assertLengthSpinePairRankingCounterexamples = do
  (duplicatedInput, inputAndZero) <- buildLengthSpinePairRankingFixture
  refused <- syntheticLengthRankingCandidate "pair-counterexample-retained"
  let original = [duplicatedInput, refused, duplicatedInput]
  (ranking, events) <- runLengthSpinePairRankingWithFakeTrace
    "healthy" Djex.LengthSMTLibInputValuesAfterSatisfiable
    defaultLengthEvaluationLimits lengthSpinePairRankingContract original
  lengthSpinePairRankingFailure ranking @?= Nothing
  map rankedLengthSpinePairCandidateOriginalIndex
      (lengthSpinePairRankingCandidates ranking) @?= [1, 0, 2]
  rankedLengthSpinePairVerifiedCandidates ranking @?=
    [refused, duplicatedInput, duplicatedInput]
  rankedLengthSpinePairPreparationRefusals ranking @?=
    [Just LengthPreparationTypedAuthorityUnavailable, Nothing, Nothing]
  receipts <- case map rankedLengthSpinePairCandidateAssessment
      $ lengthSpinePairRankingCandidates ranking of
    [ LengthSpinePairUnassessed
      , LengthSpinePairCounterexample first
      , LengthSpinePairCounterexample second
      ] -> pure [first, second]
    assessments -> assertFailure
      ("unexpected product counterexample partition: " ++ show assessments)
        >> error "unreachable"
  map Djex.validatedLengthSpinePairCounterexampleInputs receipts @?=
    replicate 2 [3]
  map Djex.validatedLengthSpinePairCounterexampleResult receipts @?=
    replicate 2 (Djex.LengthSpinePair 3 3)
  map Djex.validatedLengthSpinePairCounterexampleBasis receipts @?=
    replicate 2 Djex.ProviderIndependentFiniteSpineModel
  -- Only the first occurrence is live.  The second occurrence independently
  -- replays [3] through its own sealed product query.
  assertFakeLengthQueryEvents [0] [0] events

  let fullBank = [[1], [2], [3], [4]] :: [[Natural]]
  LengthSpinePairRankingInternal.promoteLengthSpinePairCounterexampleSeed
      [2] fullBank @?= [[2], [1], [3], [4]]
  LengthSpinePairRankingInternal.promoteLengthSpinePairCounterexampleSeed
      [5] fullBank @?= [[5], [1], [2], [3]]

  duplicatedQuery <- expectRight
      (prepareCheckedLengthSpinePairQuery
        lengthSpinePairRankingContract duplicatedInput)
    >>= expectRight
  inputAndZeroQuery <- expectRight
      (prepareCheckedLengthSpinePairQuery
        lengthSpinePairSecondOneContract inputAndZero)
    >>= expectRight
  duplicatedReceipt <- expectPairSeedReplay duplicatedQuery [[3]]
  freshReceipt <- expectPairSeedReplay inputAndZeroQuery [[3]]
  Djex.validatedLengthSpinePairCounterexampleResult duplicatedReceipt @?=
    Djex.LengthSpinePair 3 3
  Djex.validatedLengthSpinePairCounterexampleResult freshReceipt @?=
    Djex.LengthSpinePair 3 0
  Djex.validatedLengthSpinePairCounterexampleBasis freshReceipt @?=
    Djex.FiniteSpineModelUnderAssumedProviderLaws
      (pairRankingUsedProviders inputAndZero lengthSpinePairSecondOneContract)
 where
  expectPairSeedReplay query seeds = case
      LengthSpinePairRankingInternal.replayLengthSpinePairCounterexampleSeeds
        defaultLengthEvaluationLimits query seeds of
    Just ([3], receipt) -> pure receipt
    other -> assertFailure
      ("unexpected product seed replay: " ++ show other)
        >> error "unreachable"

