            )
          , (LengthRankingConfigurationArtifactPolicyField, "artifactPolicy")
          , ( LengthRankingConfigurationExecutableLaunchField
            , "executableLaunch"
            )
          ]
        applicableShape =
          [ (LengthRankingConfigurationApplicableDomainStrategyField, "strategy")
