assertLengthRankingPolicyAllIneligible :: IO ()
assertLengthRankingPolicyAllIneligible =
  withTemporaryDirectory "leant-length-config-no-open" $ \root -> do
    first <- syntheticLengthRankingCandidate "configured-ineligible-first"
    second <- syntheticLengthRankingCandidate "configured-ineligible-second"
    let executable = root </> "explicit-missing-z3"
        candidates = [first, second]
        contract = ineligibleLengthRankingContract
        executionSource = explicitLengthRankingExecutionSource
          executable Nothing Djex.LengthSMTLibInputValuesAfterSatisfiable
        policySource = explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits executionSource
          Djex.defaultLengthEvaluationLimitSource
    policy <- expectRight $ mkLengthRankingPolicy policySource
    execution <- expectRight $ Djex.mkLengthSMTLibExecutionConfig
      Djex.defaultLengthSMTLibExecutionLimits executionSource
    evaluation <- expectRight $ Djex.mkLengthEvaluationLimits
      Djex.defaultLengthEvaluationLimitSource
    direct <- expectLengthRankingWithin "direct all-ineligible configuration"
      $ rankVerifiedLengthCandidates execution evaluation contract candidates
    configured <- expectLengthRankingWithin
      "opaque-policy all-ineligible configuration"
      $ rankVerifiedLengthCandidatesWithPolicy policy contract candidates
    assertLengthRankingsEquivalent direct configured
    rankedLengthVerifiedCandidates configured @?= candidates
    map rankedLengthCandidateAssessment
        (lengthRankingCandidates configured) @?=
      [Unassessed, Unassessed]
    rankedLengthPreparationRefusals configured @?=
      replicate 2 (Just LengthPreparationTypedAuthorityUnavailable)
    lengthRankingFailure configured @?= Nothing

assertLengthRankingPolicyLiveEquivalence :: IO ()
assertLengthRankingPolicyLiveEquivalence = do
  fixture <- buildLengthRankingLiveFixture
  neutral <- syntheticLengthRankingCandidate "configured-neutral"
  trailing <- syntheticLengthRankingCandidate "configured-fallback"
  withFakeLengthSolver "healthy" $ \executable -> do
    let zero = lengthRankingFixtureZero fixture
        one = lengthRankingFixtureOne fixture
    healthy <- assertPolicyLengthRankingEquivalent executable
      Djex.LengthSMTLibStatusOnly (lengthRankingContract 0)
      [zero, neutral, one]
    case map rankedLengthCandidateAssessment
        $ lengthRankingCandidates healthy of
      [Heuristic first, Unassessed, Heuristic second] ->
        (first, second) @?=
          (Djex.SolverSatisfiable, Djex.SolverSatisfiable)
      assessments -> assertFailure $
        "unexpected configured healthy assessments: " ++ show assessments
    rankedLengthPreparationRefusals healthy @?=
      [Nothing, Just LengthPreparationTypedAuthorityUnavailable, Nothing]

    failed <- assertPolicyLengthRankingEquivalent executable
      Djex.LengthSMTLibInputValuesAfterSatisfiable
      (lengthRankingContract 0) [one, zero, trailing]
    rankedLengthVerifiedCandidates failed @?= [one, zero, trailing]
    map rankedLengthCandidateAssessment (lengthRankingCandidates failed) @?=
      replicate 3 Unassessed
    rankedLengthPreparationRefusals failed @?=
      [Nothing, Nothing, Just LengthPreparationTypedAuthorityUnavailable]
    failure <- case lengthRankingFailure failed of
      Nothing -> assertFailure "configured live failure was not retained"
      Just value -> pure value
    lengthRankingFailureClass failure @?=
      LengthRankingLiveQueryFailed
        Djex.LengthSMTLibLiveQueryCounterexampleRejected
    lengthRankingFailureCleanupIncomplete failure @?= False
    lengthRankingFailureOriginalIndex failure @?= Just 1

assertLengthRankingPolicyContractSeparation :: IO ()
assertLengthRankingPolicyContractSeparation = do
  fixture <- buildLengthRankingLiveFixture
  withFakeLengthSolver "healthy" $ \executable -> do
    let candidates =
          [ lengthRankingFixtureZero fixture
          , lengthRankingFixtureOne fixture
          ]
        policySource = explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits
          (explicitLengthRankingExecutionSource executable Nothing
            Djex.LengthSMTLibStatusOnly)
          Djex.defaultLengthEvaluationLimitSource
        sealedPolicy digest = mkLengthRankingPolicy
          $ explicitLengthRankingPolicySource
              Djex.defaultLengthSMTLibExecutionLimits
              (explicitLengthRankingExecutionSource executable digest
                Djex.LengthSMTLibStatusOnly)
              Djex.defaultLengthEvaluationLimitSource
    policy <- expectRight $ mkLengthRankingPolicy policySource
    unpinned <- expectRight $ sealedPolicy Nothing
    pinned <- expectRight $ sealedPolicy $ Just $ replicate 32 0
    lengthRankingPolicyExecutableDigestExpectation unpinned @?=
      Djex.LengthSMTLibExecutableDigestExpectationAbsent
    lengthRankingPolicyExecutableDigestExpectation pinned @?=
      Djex.LengthSMTLibExecutableDigestExpectationPresent
    let poisonContract = error
          "configuration activation forced the passive Length contract"
        disabledUnpinned = disableLengthRankingConfiguration
          unpinned poisonContract
        disabledPinned = disableLengthRankingConfiguration
          pinned poisonContract
    case activateLengthRankingConfiguration RequirePinnedExecutable
        disabledUnpinned of
      Left LengthRankingConfigurationExecutablePinRequired -> pure ()
      Right _ -> assertFailure
        "require-pinned activation accepted an unpinned policy"
    case activateLengthRankingConfiguration PermitUnpinnedExecutable
        disabledUnpinned of
      Left failure -> assertFailure $ "permit-unpinned activation failed: "
        ++ show failure
      Right _ -> pure ()
    case activateLengthRankingConfiguration RequirePinnedExecutable
        disabledPinned of
      Left failure -> assertFailure $ "pinned activation failed: "
        ++ show failure
      Right _ -> pure ()
    sealedExecution <- expectRight $ Djex.mkLengthSMTLibExecutionConfig
      Djex.defaultLengthSMTLibExecutionLimits
      $ explicitLengthRankingExecutionSource executable (Just $ replicate 32 1)
          Djex.LengthSMTLibStatusOnly
    sealedEvaluation <- expectRight $ Djex.mkLengthEvaluationLimits
      Djex.defaultLengthEvaluationLimitSource
    let bridged = lengthRankingPolicyFromValidatedComponents
          sealedExecution sealedEvaluation
    lengthRankingPolicyExecutableDigestExpectation bridged @?=
      Djex.LengthSMTLibExecutableDigestExpectationPresent
    first <- expectLengthRankingWithin "first request-owned contract"
      $ rankVerifiedLengthCandidatesWithPolicy policy
          (lengthRankingContract 0) candidates
    second <- expectLengthRankingWithin "second request-owned contract"
      $ rankVerifiedLengthCandidatesWithPolicy policy
          (lengthRankingContract 1) candidates
    mapM_ (\ranking -> do
        rankedLengthVerifiedCandidates ranking @?= candidates
        case map rankedLengthCandidateAssessment
            $ lengthRankingCandidates ranking of
          [Heuristic firstStatus, Heuristic secondStatus] ->
            (firstStatus, secondStatus) @?=
              (Djex.SolverSatisfiable, Djex.SolverSatisfiable)
          assessments -> assertFailure $ "unexpected policy assessments: "
            ++ show assessments
        rankedLengthPreparationRefusals ranking @?= [Nothing, Nothing]
        lengthRankingFailure ranking @?= Nothing)
      [first, second]

assertLengthRankingOriginProbePolicyComposition :: IO ()
assertLengthRankingOriginProbePolicyComposition = do
  fixture <- buildLengthRankingLiveFixture
  limits <- explicitLengthInputBoxLimits 0 1
  withFakeLengthSolver "query-unsat" $ \executable -> do
    let one = lengthRankingFixtureOne fixture
        zero = lengthRankingFixtureZero fixture
        candidates = [one, zero]
        contract = lengthRankingContract 0
        executionSource = explicitLengthRankingExecutionSource
          executable Nothing Djex.LengthSMTLibStatusOnly
        policySource = explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits executionSource
          Djex.defaultLengthEvaluationLimitSource
        runPolicy label policy = expectLengthRankingWithin label
          $ rankVerifiedLengthCandidatesWithPolicy policy contract candidates
    base <- expectRight $ mkLengthRankingPolicy policySource
    let boxThenOrigin = enableLengthRankingOriginProbe
          $ enableLengthRankingInputBoxValidation limits [] base
        originThenBox = enableLengthRankingInputBoxValidation limits []
          $ enableLengthRankingOriginProbe base

    first <- runPolicy "input box then origin probe" boxThenOrigin
    assertComposedRanking zero one first
    assertFakeLengthQueryEvents [0] [] =<<
      BS.readFile (executable ++ ".events")
    second <- runPolicy "origin probe then input box" originThenBox
    assertComposedRanking zero one second
    assertLengthRankingsEquivalent first second
    assertFakeLengthQueryEvents [0] [] =<<
      BS.readFile (executable ++ ".events")

    -- Both builders are persistent derivations: reusing their common base
    -- still runs both candidates live and retains the historical heuristics.
    legacy <- runPolicy "immutable base after composed builders" base
    rankedLengthVerifiedCandidates legacy @?= candidates
    map rankedLengthCandidateAssessment
        (lengthRankingCandidates legacy) @?=
      replicate 2 (Heuristic Djex.SolverUnsatisfiable)
    assertFakeLengthQueryEvents [0, 1] [] =<<
      BS.readFile (executable ++ ".events")

    verification <- verificationBatchFromReceipts candidates
    associated <- expectLengthPostVerificationWithin
      "composed origin and input-box policy association"
      $ assessVerifiedLengthCandidatesWithPolicy
          boxThenOrigin contract verification
    assertLengthPostVerificationSealed associated
    associatedRanking <- expectLengthPostVerificationRanking associated
    (postOne, postZero) <- case verifiedCandidateReceipts verification of
      [retainedOne, retainedZero] -> pure (retainedOne, retainedZero)
      receipts -> assertFailure
        ("composed verification changed cardinality: "
          ++ show (length receipts)) >> error "unreachable"
    assertComposedRanking postZero postOne associatedRanking
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates associatedRanking) @?= [1, 0]
    let presentations = presentLengthPostVerificationResult associated
    map lengthCandidatePresentationText presentations @?=
      map (detailedVerificationVariantText . verifiedCandidate)
        [postZero, postOne]
    case map lengthCandidatePresentationNote presentations of
      [Just positiveNote, Just counterexampleNote] -> do
        assertBool "origin composition lost its bounded-positive occurrence"
          $ "checked assignments = 1" `isInfixOf` positiveNote
        assertBool "origin counterexample followed the wrong occurrence"
          $ "result spine length = 1" `isInfixOf` counterexampleNote
      notes -> assertFailure
        $ "origin composition lost presentation association: " ++ show notes
    assertFakeLengthQueryEvents [0] [] =<<
      BS.readFile (executable ++ ".events")
 where
  assertComposedRanking zero one ranking = do
    lengthRankingFailure ranking @?= Nothing
    rankedLengthVerifiedCandidates ranking @?= [zero, one]
    case map rankedLengthCandidateAssessment
        $ lengthRankingCandidates ranking of
      [BoundedPositive positive, Counterexample counterexample] -> do
        Djex.validatedLengthInputBoxInclusiveMaximums positive @?= []
        Djex.validatedLengthInputBoxAssignmentCount positive @?= 1
        Djex.validatedLengthCounterexampleInputs counterexample @?= []
        Djex.validatedLengthCounterexampleResult counterexample @?= 1
      assessments -> assertFailure
        $ "unexpected composed origin/box assessments: " ++ show assessments

assertLengthRankingPositivePreferencePolicyComposition :: IO ()
assertLengthRankingPositivePreferencePolicyComposition = do
  fixture <- buildLengthRankingLiveFixture
  retained <- syntheticLengthRankingCandidate
    "positive-policy-composition-retained"
  limits <- explicitLengthInputBoxLimits 0 1
  withFakeLengthSolver "query-unsat" $ \executable -> do
    let zero = lengthRankingFixtureZero fixture
        one = lengthRankingFixtureOne fixture
        original = [retained, zero, one]
        contract = lengthRankingContract 0
        source = explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits
          (explicitLengthRankingExecutionSource executable Nothing
            Djex.LengthSMTLibStatusOnly)
          Djex.defaultLengthEvaluationLimitSource
        run label policy = expectLengthRankingWithin label
          $ rankVerifiedLengthCandidatesWithPolicy policy contract original
    base <- expectRight $ mkLengthRankingPolicy source
    let boxThenPreference = enableLengthRankingNonVacuousInputBoxPreference
          $ enableLengthRankingInputBoxValidation limits [] base
        preferenceThenBox = enableLengthRankingInputBoxValidation limits []
          $ enableLengthRankingNonVacuousInputBoxPreference base

    first <- run "box then positive preference" boxThenPreference
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates first) @?= [1, 0, 2]
    firstEvents <- BS.readFile $ executable ++ ".events"
    second <- run "positive preference then box" preferenceThenBox
    assertLengthRankingsEquivalent first second
    secondEvents <- BS.readFile $ executable ++ ".events"
    assertFakeLengthQueryEvents [0, 1] [] firstEvents
    assertFakeLengthQueryEvents [0, 1] [] secondEvents

    -- The builder is a persistent independent derivation. Preference without
    -- bounded-positive receipts is a no-op, and neither derivation mutates the
    -- common base's historical heuristic ordering.
    preferenceOnly <- run "preference without input box"
      $ enableLengthRankingNonVacuousInputBoxPreference base
    baseAgain <- run "base after positive preference derivations" base
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates preferenceOnly) @?= [0, 1, 2]
    map rankedLengthCandidateAssessment
        (lengthRankingCandidates preferenceOnly) @?=
      [ Unassessed
      , Heuristic Djex.SolverUnsatisfiable
      , Heuristic Djex.SolverUnsatisfiable
      ]
    assertLengthRankingsEquivalent preferenceOnly baseAgain

assertLengthRankingInputBoxPolicyEquivalence :: IO ()
assertLengthRankingInputBoxPolicyEquivalence = do
  fixture <- buildLengthRankingLiveFixture
  withFakeLengthSolver "query-unsat" $ \executable -> do
    let zero = lengthRankingFixtureZero fixture
        one = lengthRankingFixtureOne fixture
        candidates = [one, zero]
        contract = lengthRankingContract 0
        executionSource = explicitLengthRankingExecutionSource
          executable Nothing Djex.LengthSMTLibStatusOnly
        policySource = explicitLengthRankingPolicySource
          Djex.defaultLengthSMTLibExecutionLimits executionSource
          Djex.defaultLengthEvaluationLimitSource
    execution <- expectRight $ Djex.mkLengthSMTLibExecutionConfig
      Djex.defaultLengthSMTLibExecutionLimits executionSource
    evaluation <- expectRight $ Djex.mkLengthEvaluationLimits
      Djex.defaultLengthEvaluationLimitSource
    limits <- explicitLengthInputBoxLimits 0 1
    basePolicy <- expectRight $ mkLengthRankingPolicy policySource
    let enabledPolicy = enableLengthRankingInputBoxValidation
          limits [] basePolicy

    legacy <- expectLengthRankingWithin "legacy unsat policy"
      $ rankVerifiedLengthCandidatesWithPolicy basePolicy contract candidates
    rankedLengthVerifiedCandidates legacy @?= candidates
    map rankedLengthCandidateAssessment
        (lengthRankingCandidates legacy) @?=
      replicate 2 (Heuristic Djex.SolverUnsatisfiable)
    lengthRankingFailure legacy @?= Nothing

    direct <- expectLengthRankingWithin "direct input-box policy"
      $ rankVerifiedLengthCandidatesWithInputBoxValidation
          execution evaluation limits [] contract candidates
    configured <- expectLengthRankingWithin "opaque input-box policy"
      $ rankVerifiedLengthCandidatesWithPolicy
          enabledPolicy contract candidates
    assertLengthRankingsEquivalent direct configured
    rankedLengthVerifiedCandidates configured @?= [zero, one]
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates configured) @?= [1, 0]
    case map rankedLengthCandidateAssessment
        $ lengthRankingCandidates configured of
      [BoundedPositive positive, Counterexample counterexample] -> do
        Djex.validatedLengthInputBoxInclusiveMaximums positive @?= []
        Djex.validatedLengthInputBoxAssignmentCount positive @?= 1
        Djex.validatedLengthCounterexampleInputs counterexample @?= []
        Djex.validatedLengthCounterexampleResult counterexample @?= 1
      assessments -> assertFailure
        $ "unexpected enabled-policy assessments: " ++ show assessments

    -- Derivation is immutable: enabling the sibling policy cannot make the
    -- reusable base reinterpret a later unsat observation.
    legacyAgain <- expectLengthRankingWithin "reused legacy unsat policy"
      $ rankVerifiedLengthCandidatesWithPolicy basePolicy contract [zero]
    map rankedLengthCandidateAssessment
        (lengthRankingCandidates legacyAgain) @?=
      [Heuristic Djex.SolverUnsatisfiable]

    verification <- verificationBatchFromReceipts candidates
    associated <- expectLengthPostVerificationWithin
      "input-box policy association"
      $ assessVerifiedLengthCandidatesWithPolicy
          enabledPolicy contract verification
    assertLengthPostVerificationSealed associated
    associatedRanking <- expectLengthPostVerificationRanking associated
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates associatedRanking) @?= [1, 0]
    let presentations = presentLengthPostVerificationResult associated
    map lengthCandidatePresentationText presentations @?=
      map (detailedVerificationVariantText . verifiedCandidate) [zero, one]
    case map lengthCandidatePresentationNote presentations of
      [Just positiveNote, Just counterexampleNote] -> do
        assertBool "bounded-positive note followed the wrong occurrence"
          $ "checked assignments = 1" `isInfixOf` positiveNote
        assertBool "counterexample note followed the wrong occurrence"
          $ "result spine length = 1" `isInfixOf` counterexampleNote
      notes -> assertFailure
        $ "input-box policy lost presentation association: " ++ show notes
    events <- BS.readFile $ executable ++ ".events"
    assertFakeLengthQueryEvents [0, 1] [] events

explicitLengthRankingPolicySource
  :: Djex.LengthSMTLibExecutionLimits
  -> Djex.LengthSMTLibExecutionConfigSource
  -> Djex.LengthEvaluationLimitSource
  -> LengthRankingPolicySource
explicitLengthRankingPolicySource executionLimits executionSource
    evaluationSource = LengthRankingPolicySource
  { lengthRankingPolicyExecutionLimits = executionLimits
  , lengthRankingPolicyExecutionSource = executionSource
  , lengthRankingPolicyEvaluationSource = evaluationSource
  }

-- | The base ranking policy most live-ranking cases start from: the
-- status-only artifact policy over one unpinned fake-solver executable, with
-- default execution and evaluation limits.
statusOnlyLengthRankingPolicy
  :: FilePath
  -> Either LengthRankingConfigurationError LengthRankingPolicy
statusOnlyLengthRankingPolicy executable = mkLengthRankingPolicy
  $ explicitLengthRankingPolicySource
      Djex.defaultLengthSMTLibExecutionLimits
      (explicitLengthRankingExecutionSource executable Nothing
        Djex.LengthSMTLibStatusOnly)
      Djex.defaultLengthEvaluationLimitSource

explicitLengthRankingExecutionSource
  :: FilePath
  -> Maybe [Word8]
  -> Djex.LengthSMTLibArtifactPolicy
  -> Djex.LengthSMTLibExecutionConfigSource
explicitLengthRankingExecutionSource executable digest policy =
  (Djex.defaultLengthSMTLibExecutionConfigSource executable digest)
    { Djex.lengthSMTLibExecutionConfigSourceSolverTimeoutMilliseconds = 100
    , Djex.lengthSMTLibExecutionConfigSourceSolverResourceLimit = 4242
    , Djex.lengthSMTLibExecutionConfigSourceHostDeadlineMilliseconds = 1000
    , Djex.lengthSMTLibExecutionConfigSourceArtifactPolicy = policy
    }

assertLengthRankingPolicyError
  :: LengthRankingConfigurationError
  -> Either LengthRankingConfigurationError LengthRankingPolicy
  -> IO ()
assertLengthRankingPolicyError expected result = case result of
  Left failure -> failure @?= expected
  Right _ -> assertFailure $ "expected ranking policy failure: "
    ++ show expected

assertPolicyLengthRankingEquivalent
  :: FilePath
  -> Djex.LengthSMTLibArtifactPolicy
  -> LeanLengthContract
  -> [Verified DetailedVerificationVariant]
  -> IO LengthRanking
assertPolicyLengthRankingEquivalent executable policy contract candidates = do
  let executionSource = explicitLengthRankingExecutionSource
        executable Nothing policy
  policyConfiguration <- expectRight $ mkLengthRankingPolicy
    $ explicitLengthRankingPolicySource
        Djex.defaultLengthSMTLibExecutionLimits executionSource
        Djex.defaultLengthEvaluationLimitSource
  execution <- expectRight $ Djex.mkLengthSMTLibExecutionConfig
    Djex.defaultLengthSMTLibExecutionLimits executionSource
  evaluation <- expectRight $ Djex.mkLengthEvaluationLimits
    Djex.defaultLengthEvaluationLimitSource
  direct <- expectLengthRankingWithin "direct live configuration"
    $ rankVerifiedLengthCandidates execution evaluation contract candidates
  policyRanked <- expectLengthRankingWithin "separate policy and contract"
    $ rankVerifiedLengthCandidatesWithPolicy policyConfiguration contract
        candidates
  assertLengthRankingsEquivalent direct policyRanked
  pure policyRanked

expectLengthRankingWithin
  :: String
  -> IO (Either LengthRankingInputError LengthRanking)
  -> IO LengthRanking
expectLengthRankingWithin label action = do
  bounded <- timeout 8000000 action
  case bounded of
    Nothing -> assertFailure $ label ++ " exceeded its outer bound"
    Just result -> expectRight result

assertLengthRankingsEquivalent :: LengthRanking -> LengthRanking -> IO ()
assertLengthRankingsEquivalent direct configured = do
  rankedLengthVerifiedCandidates configured @?=
    rankedLengthVerifiedCandidates direct
  map rankedLengthCandidateAssessment
      (lengthRankingCandidates configured) @?=
    map rankedLengthCandidateAssessment (lengthRankingCandidates direct)
  map rankedLengthCandidateOriginalIndex
      (lengthRankingCandidates configured) @?=
    map rankedLengthCandidateOriginalIndex
      (lengthRankingCandidates direct)
  rankedLengthPreparationRefusals configured @?=
    rankedLengthPreparationRefusals direct
  lengthRankingFailure configured @?= lengthRankingFailure direct

data LengthRankingLiveFixture = LengthRankingLiveFixture
  { lengthRankingFixtureZero
      :: Verified DetailedVerificationVariant
  , lengthRankingFixtureOne
      :: Verified DetailedVerificationVariant
  }

assertLengthPreparationRefusalClasses :: IO ()
assertLengthPreparationRefusalClasses = do
  let poison label = error $ "preparation sanitizer forced " ++ label
      handoffRefusals =
        [ LengthHandoffNotTypedRoute $ poison "route"
        , LengthHandoffMissingSemanticSidecar
        , LengthHandoffRetargetedFragments
        , LengthHandoffPremisesPresent
        , LengthHandoffSearchGoalChanged
        , LengthHandoffSourceGoalVariableMissing $ poison "source variable"
        , LengthHandoffRequestContextsPresent $ poison "request contexts"
        , LengthHandoffRequestGoalChanged
        , LengthHandoffTypedGraphLost $ poison "typed graph"
        , LengthHandoffRendererRejected $ poison "renderer refusal"
        , LengthHandoffRendererNotUnique $ poison "renderer alternatives"
        , LengthHandoffRendererOrdinalChanged $ poison "renderer ordinal"
        , LengthHandoffRendererTextChanged
            (poison "rendered candidate") (poison "accepted candidate")
        , LengthHandoffFamilyUnavailable $ poison "family"
        , LengthHandoffConstructorUnavailable
            (poison "family constructor") (poison "constructor")
        , LengthHandoffProviderUnavailable $ poison "provider"
        , LengthHandoffProviderAmbiguous
            (poison "ambiguous provider") (poison "provider matches")
        , LengthHandoffProviderVariableMissing
            (poison "provider variable") (poison "provider source")
        , LengthHandoffExactCasePolicyRequiresTargetRoles
        , LengthHandoffSessionRejected
            $ LengthSessionTargetArgumentRoleLimitExceeded
                (poison "session role maximum")
                (poison "session role observed")
        , LengthHandoffContractRejected
            $ Djex.LengthContractTargetArgumentRoleArityMismatch
                (poison "contract target arity")
                (poison "contract role arity")
        , LengthHandoffProblemRejected
            $ Djex.LengthProblemUnobservedTargetArgumentDemanded
                (poison "unobserved target ordinal")
                (poison "unobserved target demand site")
        ]
      expectedHandoffClasses =
        [ LengthPreparationUnsupportedRoute
        , LengthPreparationTypedAuthorityUnavailable
        , LengthPreparationCandidateAssociationRejected
        , LengthPreparationCandidateAssociationRejected
        , LengthPreparationCandidateAssociationRejected
        , LengthPreparationCandidateAssociationRejected
        , LengthPreparationCandidateAssociationRejected
        , LengthPreparationCandidateAssociationRejected
        , LengthPreparationTypedAuthorityUnavailable
        , LengthPreparationRenderingAssociationRejected
        , LengthPreparationRenderingAssociationRejected
        , LengthPreparationRenderingAssociationRejected
        , LengthPreparationRenderingAssociationRejected
        , LengthPreparationSpineBindingUnavailable
        , LengthPreparationSpineBindingUnavailable
        , LengthPreparationProviderBindingUnavailable
        , LengthPreparationProviderBindingUnavailable
        , LengthPreparationProviderBindingUnavailable
        , LengthPreparationContractRejected
        , LengthPreparationSessionRejected
        , LengthPreparationContractRejected
        , LengthPreparationCandidateSemanticsRejected
        ]
      queryRefusals =
        [ Djex.LengthSMTLibQuotientDivisorZero
        , Djex.LengthSMTLibModuloDivisorZero
        , Djex.LengthSMTLibUnexpectedResultVariable
        , Djex.LengthSMTLibInputVariableOutOfRange 0 0
        , Djex.LengthSMTLibNumeralBitLimitExceeded
            Djex.LengthSMTLibLiteralNumeral 1 0
        , Djex.LengthSMTLibCommandByteLimitExceeded
            Djex.LengthSMTLibCheckCommand 1 0
        , Djex.LengthSMTLibFingerprintByteLimitExceeded 1 0
        ]
      classes = [minBound .. maxBound]
      expectedCodes =
        [ "unsupported-route"
        , "typed-authority-unavailable"
        , "candidate-association-rejected"
        , "rendering-association-rejected"
        , "spine-binding-unavailable"
        , "provider-binding-unavailable"
        , "session-rejected"
        , "contract-rejected"
        , "candidate-semantics-rejected"
        , "query-construction-rejected"
        ]
  map lengthHandoffPreparationRefusalClass handoffRefusals @?=
    expectedHandoffClasses
  map lengthQueryPreparationRefusalClass queryRefusals @?=
    replicate 7 LengthPreparationQueryConstructionRejected
  map lengthPreparationRefusalClassCode classes @?= expectedCodes
  Set.size (Set.fromList expectedCodes) @?= length expectedCodes
  let sanitized = show $ lengthHandoffPreparationRefusalClass
        $ LengthHandoffRendererTextChanged
            "private-rendered-candidate" "private-accepted-candidate"
  assertBool "preparation sanitizer retained renderer payload text"
    $ not $ "private-" `isInfixOf` sanitized

assertLengthRankingInputBound :: IO ()
assertLengthRankingInputBound = do
  candidate <- syntheticLengthRankingCandidate "synthetic-bound"
  let maximumCandidates =
        Djex.defaultLengthSMTLibLiveSessionMaximumQueries
      exact = replicate (fromIntegral maximumCandidates) candidate
      unopened = error "Length ranking opened a worker during input admission"
  admitted <- rankVerifiedLengthCandidates unopened
    defaultLengthEvaluationLimits ineligibleLengthRankingContract exact
  exactRanking <- expectRight admitted
  length (lengthRankingCandidates exactRanking) @?=
    fromIntegral maximumCandidates
  lengthRankingFailure exactRanking @?= Nothing
  map rankedLengthCandidateAssessment
      (lengthRankingCandidates exactRanking) @?=
    replicate (fromIntegral maximumCandidates) Unassessed
  rankedLengthPreparationRefusals exactRanking @?=
    replicate (fromIntegral maximumCandidates)
      (Just LengthPreparationTypedAuthorityUnavailable)

  bounded <- timeout 1000000 $ rankVerifiedLengthCandidates unopened
    defaultLengthEvaluationLimits ineligibleLengthRankingContract
    $ repeat candidate
  case bounded of
    Just (Left (LengthRankingInputLimitExceeded admittedMaximum observed)) -> do
      admittedMaximum @?= maximumCandidates
      observed @?= maximumCandidates + 1
    Just (Right _) -> assertFailure
      "cyclic maximum-plus-one ranking input was admitted"
    Nothing -> assertFailure
      "cyclic maximum-plus-one ranking input was not rejected productively"

assertLengthRankingAllIneligible :: IO ()
assertLengthRankingAllIneligible = do
  first <- syntheticLengthRankingCandidate "synthetic-first"
  second <- syntheticLengthRankingCandidate "synthetic-second"
  let original = [first, second]
      unopened = error "all-ineligible Length ranking opened a live session"
  result <- rankVerifiedLengthCandidates unopened
    defaultLengthEvaluationLimits ineligibleLengthRankingContract original
  ranking <- expectRight result
  lengthRankingFailure ranking @?= Nothing
  rankedLengthVerifiedCandidates ranking @?= original
  map rankedLengthCandidateAssessment (lengthRankingCandidates ranking) @?=
    [Unassessed, Unassessed]
  rankedLengthPreparationRefusals ranking @?=
    replicate 2 (Just LengthPreparationTypedAuthorityUnavailable)

assertLengthRankingNeutralStatuses :: IO ()
assertLengthRankingNeutralStatuses = do
  fixture <- buildLengthRankingLiveFixture
  ineligible <- syntheticLengthRankingCandidate "neutral-ineligible"
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      original =
        [zero, ineligible, one]
      cases =
        [ ( "healthy"
          , Djex.LengthSMTLibStatusOnly
          , Djex.SolverSatisfiable
          )
        , ( "query-unsat"
          , Djex.LengthSMTLibInputValuesAfterSatisfiable
          , Djex.SolverUnsatisfiable
          )
        , ( "query-unknown"
          , Djex.LengthSMTLibInputValuesAfterSatisfiable
          , Djex.SolverUnknown
          )
        ]
  mapM_ (assertNeutralCase original) cases

assertNeutralCase
  :: [Verified DetailedVerificationVariant]
  -> (String, Djex.LengthSMTLibArtifactPolicy, Djex.SolverStatus)
  -> IO ()
assertNeutralCase original (mode, policy, expectedStatus) = do
  ranking <- runLengthRankingWithFake mode policy
    (lengthRankingContract 0) original
  lengthRankingFailure ranking @?= Nothing
  rankedLengthVerifiedCandidates ranking @?= original
  case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates ranking of
    [Heuristic zero, Unassessed, Heuristic one] ->
      (zero, one) @?= (expectedStatus, expectedStatus)
    assessments -> assertFailure $ "unexpected neutral Length assessments: "
      ++ show assessments
  rankedLengthPreparationRefusals ranking @?=
    [Nothing, Just LengthPreparationTypedAuthorityUnavailable, Nothing]

assertLengthRankingCounterexampleDemotion :: IO ()
assertLengthRankingCounterexampleDemotion = do
  fixture <- buildLengthRankingLiveFixture
  retainedFirst <- syntheticLengthRankingCandidate "retained-first"
  retainedSecond <- syntheticLengthRankingCandidate "retained-second"
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      contract = lengthRankingContract 2
      original = [zero, retainedFirst, one, retainedSecond]
      expected = [retainedFirst, retainedSecond, zero, one]
  zeroProblem <- expectRight $ prepareCheckedLengthProblem contract zero
  oneProblem <- expectRight $ prepareCheckedLengthProblem contract one
  zeroQuery <- expectRight (prepareCheckedLengthQuery contract zero)
    >>= expectRight
  oneQuery <- expectRight (prepareCheckedLengthQuery contract one)
    >>= expectRight
  assertBool "distinct checked providers shared a Length query identity"
    $ Djex.lengthSMTLibQueryFingerprint zeroQuery /=
        Djex.lengthSMTLibQueryFingerprint oneQuery
  assertLengthRankingQueryAssociation zeroProblem zeroQuery
  assertLengthRankingQueryAssociation oneProblem oneQuery
  (ranking, events) <- runLengthRankingWithFakeTrace "healthy"
    Djex.LengthSMTLibInputValuesAfterSatisfiable
    contract original
  lengthRankingFailure ranking @?= Nothing
  length (lengthRankingCandidates ranking) @?= length original
  rankedLengthVerifiedCandidates ranking @?= expected
  case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates ranking of
    [Unassessed, Unassessed, Counterexample zeroReceipt,
        Counterexample oneReceipt] -> do
      assertLengthCounterexampleReceipt 0 zeroReceipt
      assertLengthCounterexampleReceipt 1 oneReceipt
      Djex.validatedLengthCounterexampleBasis zeroReceipt @?=
        Djex.FiniteSpineModelUnderAssumedProviderLaws
          (checkedLengthCandidateUsedProviders
            $ checkedLengthProblemCandidate zeroProblem)
      Djex.validatedLengthCounterexampleBasis oneReceipt @?=
        Djex.FiniteSpineModelUnderAssumedProviderLaws
          (checkedLengthCandidateUsedProviders
            $ checkedLengthProblemCandidate oneProblem)
    assessments -> assertFailure $
      "unexpected stable counterexample partition: " ++ show assessments
  rankedLengthPreparationRefusals ranking @?=
    [ Just LengthPreparationTypedAuthorityUnavailable
    , Just LengthPreparationTypedAuthorityUnavailable
    , Nothing
    , Nothing
    ]
  assertFakeLengthQueryEvents [0] [] events

assertLengthRankingCounterexampleSeedReplay :: IO ()
assertLengthRankingCounterexampleSeedReplay = do
  (contract, verified) <- buildRoleAwareMapFixture
  problem <- expectRight $ prepareCheckedLengthProblem contract verified
  let expectedProviders = checkedLengthCandidateUsedProviders
        $ checkedLengthProblemCandidate problem
  (ranking, events) <- runLengthRankingWithFakeTrace "healthy"
    Djex.LengthSMTLibInputValuesAfterSatisfiable
    contract [verified, verified]
  lengthRankingFailure ranking @?= Nothing
  map rankedLengthCandidateOriginalIndex
      (lengthRankingCandidates ranking) @?= [0, 1]
  case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates ranking of
    [Counterexample first, Counterexample second] -> do
      map Djex.validatedLengthCounterexampleInputs [first, second] @?=
        [[3], [3]]
      map Djex.validatedLengthCounterexampleResult [first, second] @?=
        [3, 3]
      map Djex.validatedLengthCounterexampleBasis [first, second] @?=
        replicate 2
          (Djex.FiniteSpineModelUnderAssumedProviderLaws expectedProviders)
    assessments -> assertFailure $
      "unexpected seed-replayed assessments: " ++ show assessments
  assertFakeLengthQueryEvents [0] [0] events

assertLengthRankingCounterexampleSeedArityMismatch :: IO ()
assertLengthRankingCounterexampleSeedArityMismatch = do
  fixture <- buildLengthRankingLiveFixture
  identity <- buildOneInputLengthRankingCandidate
  let contract = lengthRankingContract 2
      candidates = [lengthRankingFixtureZero fixture, identity]
  identityQuery <- expectRight (prepareCheckedLengthQuery contract identity)
    >>= expectRight
  length (lengthSMTLibQueryInputSymbols identityQuery) @?= 1
  (ranking, events) <- runLengthRankingWithFakeTrace "healthy"
    Djex.LengthSMTLibInputValuesAfterSatisfiable contract candidates
  lengthRankingFailure ranking @?= Nothing
  rankedLengthVerifiedCandidates ranking @?= candidates
  case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates ranking of
    [Counterexample zeroReceipt, Counterexample identityReceipt] -> do
      Djex.validatedLengthCounterexampleInputs zeroReceipt @?= []
      Djex.validatedLengthCounterexampleResult zeroReceipt @?= 0
      Djex.validatedLengthCounterexampleInputs identityReceipt @?= [3]
      Djex.validatedLengthCounterexampleResult identityReceipt @?= 3
      Djex.validatedLengthCounterexampleBasis identityReceipt @?=
        Djex.ProviderIndependentFiniteSpineModel
    assessments -> assertFailure $
      "unexpected arity-mismatch assessments: " ++ show assessments
  assertFakeLengthQueryEvents [0, 1] [1] events

assertLengthRankingCounterexampleSeedMRU :: IO ()
assertLengthRankingCounterexampleSeedMRU = do
  (contract, arityCandidates) <- buildLengthSeedBankArityFixture
  refused <- syntheticLengthRankingCandidate "seed-bank-preparation-refusal"
  (zeroInput, oneInput, twoInput, threeInput, fourInput) <-
    case arityCandidates of
    [zero, one, two, three, four] -> pure (zero, one, two, three, four)
    _ -> assertFailure "the bounded projection fixture changed cardinality"
      >> error "unreachable"
  let candidates =
        [ zeroInput
        , oneInput
        , twoInput
        , threeInput
        , refused
        , twoInput
        , zeroInput
        , fourInput
        , oneInput
        , twoInput
        ]
      expectedCounterexampleInputs =
        [ []
        , [3]
        , [3, 5]
        , [3, 5, 7]
        , [3, 5]
        , []
        , [3, 5, 7, 9]
        , [3]
        , [3, 5]
        ]
  (ranking, events) <- runLengthRankingWithFakeTrace "healthy"
    Djex.LengthSMTLibInputValuesAfterSatisfiable
    contract candidates
  lengthRankingFailure ranking @?= Nothing
  -- Stable counterexample demotion moves only the preparation refusal.  The
  -- retained original indices also make every repeated occurrence explicit.
  map rankedLengthCandidateOriginalIndex
      (lengthRankingCandidates ranking) @?=
    [4, 0, 1, 2, 3, 5, 6, 7, 8, 9]
  rankedLengthVerifiedCandidates ranking @?=
    refused : [ zeroInput, oneInput, twoInput, threeInput, twoInput
              , zeroInput, fourInput, oneInput, twoInput
              ]
  rankedLengthPreparationRefusals ranking @?=
    Just LengthPreparationTypedAuthorityUnavailable : replicate 9 Nothing
  case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates ranking of
    Unassessed : counterexamples -> do
      actualInputs <- mapM extractCounterexampleInputs counterexamples
      actualInputs @?= expectedCounterexampleInputs
    assessments -> assertFailure $
      "unexpected MRU seed-bank assessments: " ++ show assessments
  -- The first four distinct vectors are live ordinals 0..3.  The repeated
  -- arity-two query must skip the newer arity-three vector and hit the older
  -- vector, promoting it.  The following arity-zero hit proves that promotion
  -- removed the exact duplicate instead of consuming a slot.  Arity four is
  -- the fifth distinct vector and evicts arity one, which therefore becomes
  -- actual-live ordinal 5.  The final arity-two hit proves its earlier hit was
  -- promoted.  Both all-miss paths retain compact actual-live ordinals.
  assertFakeLengthQueryEvents [0 .. 5] [1 .. 5] events
 where
  extractCounterexampleInputs assessment = case assessment of
    Counterexample receipt ->
      pure $ Djex.validatedLengthCounterexampleInputs receipt
    other -> assertFailure
      ("MRU seed-bank candidate was not a counterexample: " ++ show other)
        >> error "unreachable"

assertLengthRankingCounterexampleSeedNewestFirst :: IO ()
assertLengthRankingCounterexampleSeedNewestFirst = do
  identity <- buildOneInputLengthRankingCandidate
  query <- expectRight
      (prepareCheckedLengthQuery (lengthRankingContract 2) identity)
    >>= expectRight
  -- Both distinct one-input vectors violate the same later identity query.
  -- The two remaining entries make each case a full-capacity bank but cannot
  -- match that query's arity.
  mapM_ (assertIndependentCounterexample query) [[5], [3]]
  assertNewestFirst query [[5], [3], [], [3, 5]] [5]
  assertNewestFirst query [[3], [5], [], [3, 5]] [3]
  let oversizedMissBank =
        [] : [3, 5] : [3, 5, 7] : [3, 5, 7, 9]
          : error "replay forced a fifth bank entry"
  case LengthRankingInternal.replayCounterexampleSeeds
      defaultLengthEvaluationLimits query oversizedMissBank of
    Nothing -> pure ()
    Just _ -> assertFailure
      "an arity-mismatched oversized bank unexpectedly replayed"
  strictPromotion <- try $ evaluate $
    LengthRankingInternal.promoteCounterexampleSeed
      [error "promoted input vector remained lazy"] []
  case strictPromotion :: Either SomeException [[Natural]] of
    Left _ -> pure ()
    Right _ -> assertFailure
      "counterexample seed promotion retained a lazy input vector"
 where
  assertIndependentCounterexample query inputs = case inputs of
    [expectedResult] -> case
        Djex.replayLengthSMTLibCounterexampleInputs
          defaultLengthEvaluationLimits query inputs of
      Left failure -> assertFailure $
        "applicable newest-first fixture input was rejected: " ++ show failure
      Right Nothing -> assertFailure $
        "applicable newest-first fixture input satisfied the contract: "
          ++ show inputs
      Right (Just receipt) -> do
        Djex.validatedLengthCounterexampleInputs receipt @?= inputs
        Djex.validatedLengthCounterexampleResult receipt @?= expectedResult
    _ -> assertFailure "newest-first fixture input was not unary"

  assertNewestFirst query bank expected = case
      LengthRankingInternal.replayCounterexampleSeeds
        defaultLengthEvaluationLimits query bank of
    Nothing -> assertFailure
      "the full counterexample seed bank produced no replay hit"
    Just (inputs, receipt) -> case expected of
      [expectedResult] -> do
        inputs @?= expected
        Djex.validatedLengthCounterexampleInputs receipt @?= expected
        Djex.validatedLengthCounterexampleResult receipt @?= expectedResult
      _ -> assertFailure "newest-first expected input was not unary"

assertLengthRankingCounterexampleSeedFreshReceipt :: IO ()
assertLengthRankingCounterexampleSeedFreshReceipt = do
  (contract, scaled, independent) <-
    buildScaledProviderReplayFixture
  scaledProblem <- expectRight
    $ prepareCheckedLengthProblem contract scaled
  independentProblem <- expectRight
    $ prepareCheckedLengthProblem contract independent
  scaledQuery <- expectRight (prepareCheckedLengthQuery contract scaled)
    >>= expectRight
  independentQuery <- expectRight
      (prepareCheckedLengthQuery contract independent)
    >>= expectRight
  assertBool "distinct replay fixture problems shared a query identity"
    $ lengthSMTLibQueryFingerprint scaledQuery /=
        lengthSMTLibQueryFingerprint independentQuery
  checkedLengthCandidateResult
      (checkedLengthProblemCandidate scaledProblem) @?=
    LengthScale 2 (LengthVariable $ LengthInput 0)
  checkedLengthCandidateResult
      (checkedLengthProblemCandidate independentProblem) @?=
    LengthVariable (LengthInput 0)
  let scaledProviders = checkedLengthCandidateUsedProviders
        $ checkedLengthProblemCandidate scaledProblem
  length scaledProviders @?= 1
  checkedLengthCandidateUsedProviders
      (checkedLengthProblemCandidate independentProblem) @?= []
  (ranking, events) <- runLengthRankingWithFakeTrace "healthy"
    Djex.LengthSMTLibInputValuesAfterSatisfiable contract
    [scaled, independent, scaled, independent]
  lengthRankingFailure ranking @?= Nothing
  map rankedLengthCandidateOriginalIndex
      (lengthRankingCandidates ranking) @?= [0, 1, 2, 3]
  case map rankedLengthCandidateAssessment
      $ lengthRankingCandidates ranking of
    [ Counterexample firstScaled
      , Counterexample firstIndependent
      , Counterexample secondScaled
      , Counterexample secondIndependent
      ] -> do
        let receipts =
              [ firstScaled
              , firstIndependent
              , secondScaled
              , secondIndependent
              ]
        map Djex.validatedLengthCounterexampleInputs receipts @?=
          replicate 4 [3]
        map Djex.validatedLengthCounterexampleResult receipts @?=
          [6, 3, 6, 3]
        map Djex.validatedLengthCounterexampleBasis receipts @?=
          [ Djex.FiniteSpineModelUnderAssumedProviderLaws scaledProviders
          , Djex.ProviderIndependentFiniteSpineModel
          , Djex.FiniteSpineModelUnderAssumedProviderLaws scaledProviders
          , Djex.ProviderIndependentFiniteSpineModel
          ]
    assessments -> assertFailure $
      "unexpected query-owned replay assessments: " ++ show assessments
  -- Only the first occurrence is live.  Every later equal-vector hit must
  -- rebuild the result and provider basis from its own checked query.
  assertFakeLengthQueryEvents [0] [0] events

assertLengthRankingCounterexampleSeedHeuristicIsolation :: IO ()
assertLengthRankingCounterexampleSeedHeuristicIsolation = do
  identity <- buildOneInputLengthRankingCandidate
  refused <- syntheticLengthRankingCandidate "heuristic-seed-refusal"
  let candidates = [identity, refused, identity]
  (ranking, events) <- runLengthRankingWithFakeTrace "healthy"
    Djex.LengthSMTLibStatusOnly (lengthRankingContract 0) candidates
  lengthRankingFailure ranking @?= Nothing
  rankedLengthVerifiedCandidates ranking @?= candidates
  map rankedLengthCandidateAssessment
      (lengthRankingCandidates ranking) @?=
    [ Heuristic Djex.SolverSatisfiable
    , Unassessed
    , Heuristic Djex.SolverSatisfiable
    ]
  rankedLengthPreparationRefusals ranking @?=
    [ Nothing
    , Just LengthPreparationTypedAuthorityUnavailable
    , Nothing
    ]
  -- A heuristic has no input receipt to seed, and a preparation refusal has
  -- no bank effect.  The repeated exact query must therefore remain the next
  -- compact live ordinal rather than becoming a replay hit.
  assertFakeLengthQueryEvents [0, 1] [] events

assertLengthRankingCounterexampleSeedEvaluationLimits :: IO ()
assertLengthRankingCounterexampleSeedEvaluationLimits = do
  (contract, scaled, independent) <- buildScaledProviderReplayFixture
  evaluation <- expectRight $ Djex.mkLengthEvaluationLimits
    Djex.LengthEvaluationLimitSource
      { Djex.lengthEvaluationLimitSourceAssignmentValueBits = 2
      , Djex.lengthEvaluationLimitSourceIntermediateValueBits = 2
      }
  (ranking, events) <- runLengthRankingWithFakeTraceWithEvaluation
    "healthy" Djex.LengthSMTLibInputValuesAfterSatisfiable evaluation
    contract [independent, scaled]
  rankedLengthVerifiedCandidates ranking @?= [independent, scaled]
  map rankedLengthCandidateAssessment
      (lengthRankingCandidates ranking) @?=
    [Unassessed, Unassessed]
  rankedLengthPreparationRefusals ranking @?= [Nothing, Nothing]
  failure <- case lengthRankingFailure ranking of
    Nothing -> assertFailure
      "a seed replay bypassed the caller's intermediate-value limit"
        >> error "unreachable"
    Just retained -> pure retained
  lengthRankingFailureClass failure @?=
    LengthRankingLiveQueryFailed
      Djex.LengthSMTLibLiveQueryCounterexampleRejected
  lengthRankingFailureCleanupIncomplete failure @?= False
  lengthRankingFailureOriginalIndex failure @?= Just 1
  -- The independent query admits input/result 3 and seeds [3].  Replaying it
  -- against the scaled query must reject intermediate result 6 under this
  -- nondefault two-bit limit, then fall through to compact live ordinal 1.
  -- Live validation rejects the same model and triggers atomic fallback.
  assertFakeLengthQueryEvents [0, 1] [0, 1] events

assertLengthRankingOriginProbeOrdering :: IO ()
assertLengthRankingOriginProbeOrdering = do
  (contract, arityCandidates) <- buildLengthSeedBankArityFixture
  (zeroInput, oneInput, threeInput) <- case arityCandidates of
    zero : one : _ : three : _ -> pure (zero, one, three)
    _ -> assertFailure "the origin-probe arity fixture changed cardinality"
      >> error "unreachable"
  let hitContract = contract
        { leanLengthContractSource = LengthContractSource
            { lengthContractPrecondition = LengthTruth True
            , lengthContractPostcondition = LengthEqual
                (LengthVariable LengthResult) (LengthLiteral 2)
            }
        }
      coldCandidates = [zeroInput, oneInput, threeInput]
      queryIdentity query =
        ( fingerprintCanonicalBytes $ lengthSMTLibQueryFingerprint query
        , lengthSMTLibQueryCheckBytes query
        , lengthSMTLibQueryInputSymbols query
        , lengthSMTLibQueryInputValueRequestBytes query
        )
      prepareQuery candidate =
        expectRight (prepareCheckedLengthQuery hitContract candidate)
          >>= expectRight
  beforeQueries <- mapM prepareQuery coldCandidates
  coldRuns <- mapM
    (\candidate -> runLengthRankingWithFakeTraceWithOriginProbe
      "healthy" Djex.LengthSMTLibInputValuesAfterSatisfiable
      defaultLengthEvaluationLimits hitContract [candidate]) coldCandidates
  coldReceipts <- mapM expectColdReceipt coldRuns
  map Djex.validatedLengthCounterexampleInputs coldReceipts @?=
    [[], [0], [0, 0, 0]]
  map Djex.validatedLengthCounterexampleResult coldReceipts @?= [1, 0, 0]
  afterQueries <- mapM prepareQuery coldCandidates
  map queryIdentity afterQueries @?= map queryIdentity beforeQueries

  -- The lexical worker and its capability probe still precede the pure
  -- candidate loop.  An origin hit skips a query transaction, not session
  -- establishment, so a capability failure atomically withholds that hit.
  (sessionFailureRanking, sessionFailureEvents) <-
    runLengthRankingWithFakeTraceWithOriginProbe
      "wrong-echo" Djex.LengthSMTLibInputValuesAfterSatisfiable
      defaultLengthEvaluationLimits hitContract [zeroInput]
  map rankedLengthCandidateAssessment
      (lengthRankingCandidates sessionFailureRanking) @?= [Unassessed]
  sessionFailure <- case lengthRankingFailure sessionFailureRanking of
    Nothing -> assertFailure "origin probing bypassed session establishment"
      >> error "unreachable"
    Just retained -> pure retained
  case lengthRankingFailureClass sessionFailure of
    LengthRankingLiveSessionFailed _ -> pure ()
    failureClass -> assertFailure
      $ "unexpected origin session failure: " ++ show failureClass
  assertFakeLengthQueryEvents [] [] sessionFailureEvents

  let replayCandidates = [zeroInput, zeroInput, oneInput, oneInput]
  (replayRanking, replayEvents) <-
    runLengthRankingWithFakeTraceWithOriginProbe
      "healthy" Djex.LengthSMTLibInputValuesAfterSatisfiable
      defaultLengthEvaluationLimits contract replayCandidates
  lengthRankingFailure replayRanking @?= Nothing
  map rankedLengthCandidateOriginalIndex
      (lengthRankingCandidates replayRanking) @?= [0, 1, 2, 3]
  replayReceipts <- mapM expectOriginCounterexample
    $ map rankedLengthCandidateAssessment
    $ lengthRankingCandidates replayRanking
  map Djex.validatedLengthCounterexampleInputs replayReceipts @?=
    [[], [], [3], [3]]
  map Djex.validatedLengthCounterexampleResult replayReceipts @?=
    [1, 1, 3, 3]
  -- The second nullary candidate and final unary candidate are MRU hits.  The
  -- intervening unary origin miss reaches the first compact live ordinal even
  -- though two candidates have already been assessed without live queries.
  assertFakeLengthQueryEvents [0] [0] replayEvents
  LengthRankingInternal.promoteCounterexampleSeed []
      ([[3], [], [5], []] :: [[Natural]]) @?=
    [[], [3], [5]]
 where
  expectOriginCounterexample assessment = case assessment of
    Counterexample receipt -> pure receipt
    other -> assertFailure
      ("expected an origin or seed counterexample: " ++ show other)
        >> error "unreachable"

  expectColdReceipt (ranking, events) = do
    lengthRankingFailure ranking @?= Nothing
    map rankedLengthCandidateOriginalIndex
        (lengthRankingCandidates ranking) @?= [0]
    assertFakeLengthQueryEvents [] [] events
    case map rankedLengthCandidateAssessment
        $ lengthRankingCandidates ranking of
      [assessment] -> expectOriginCounterexample assessment
      assessments -> assertFailure
        ("cold origin run changed cardinality: " ++ show assessments)
          >> error "unreachable"

assertLengthRankingOriginProbeAtomicFallback :: IO ()
assertLengthRankingOriginProbeAtomicFallback = do
  (contract, arityCandidates) <- buildLengthSeedBankArityFixture
  (zeroInput, oneInput) <- case arityCandidates of
    zero : one : _ -> pure (zero, one)
    _ -> assertFailure "the origin failure fixture changed cardinality"
      >> error "unreachable"
  providerLaws <- case leanLengthContractProviderLaws contract of
    zeroLaw : oneLaw : remaining -> pure
      $ zeroLaw
      : oneLaw { leanLengthProviderLawTransfer = LengthLiteral 2 }
      : remaining
    _ -> assertFailure "the origin failure provider inventory changed"
      >> error "unreachable"
  evaluation <- expectRight $ Djex.mkLengthEvaluationLimits
    Djex.defaultLengthEvaluationLimitSource
      { Djex.lengthEvaluationLimitSourceIntermediateValueBits = 1 }
  trailing <- syntheticLengthRankingCandidate "origin-failure-trailing"
  let failingContract = contract
        { leanLengthContractProviderLaws = providerLaws }
      original = [zeroInput, oneInput, trailing]
  (ranking, events) <- runLengthRankingWithFakeTraceWithOriginProbe
    "healthy" Djex.LengthSMTLibStatusOnly evaluation failingContract original
  rankedLengthVerifiedCandidates ranking @?= original
  map rankedLengthCandidateAssessment (lengthRankingCandidates ranking) @?=
    replicate 3 Unassessed
  rankedLengthPreparationRefusals ranking @?=
    [Nothing, Nothing, Just LengthPreparationTypedAuthorityUnavailable]
  failure <- case lengthRankingFailure ranking of
    Nothing -> assertFailure "origin evaluation rejection was not retained"
      >> error "unreachable"
    Just retained -> pure retained
  lengthRankingFailureClass failure @?=
    LengthRankingOriginProbeEvaluationFailed
      (Djex.LengthEvaluationValueBitLimitExceeded
        Djex.LengthIntermediateValue 1 2)
  lengthRankingFailureCleanupIncomplete failure @?= False
  lengthRankingFailureOriginalIndex failure @?= Just 1
  assertFakeLengthQueryEvents [] [] events

assertLengthRankingAtomicFallback :: IO ()
assertLengthRankingAtomicFallback = do
  fixture <- buildLengthRankingLiveFixture
  trailing <- syntheticLengthRankingCandidate "fallback-trailing"
  let zero = lengthRankingFixtureZero fixture
      one = lengthRankingFixtureOne fixture
      original = [one, one, zero, trailing]
  (ranking, events) <- runLengthRankingWithFakeTrace "healthy"
    Djex.LengthSMTLibInputValuesAfterSatisfiable
    (lengthRankingContract 0) original
  rankedLengthVerifiedCandidates ranking @?= original
  map rankedLengthCandidateAssessment (lengthRankingCandidates ranking) @?=
